(150, '_site_transient_feed_d117b5738fbd35bd8c0391cda1f2b5d9', 'a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:112:\"\n	\n	\n	\n	\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"WordPress Planet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"en\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress Planet - http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:50:{i:0;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:113:\"Gutenberg Times: Gutenberg 24.0, the road to 7.2, a new default theme named Ipsum, and more—Weekend Edition 377\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=47181\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:119:\"https://gutenbergtimes.com/gutenberg-24-0-the-road-to-7-2-a-new-default-theme-named-ipsum-and-more-weekend-edition-377/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:34343:\"<p class=\"wp-block-paragraph\">Howdy,</p>\n\n\n\n<p class=\"wp-block-paragraph\">Before anything else: if you maintain WordPress sites, go update them. <a href=\"https://wordpress.org/news/2026/09/wordpress-7-1-2-release/\"><strong>WordPress 7.1.2</strong></a> shipped on September 22 to patch a single critical vulnerability in page template resolution, one that lets an unauthenticated attacker load a chosen PHP file from outside your active theme&#8217;s directories.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now let&#8217;s move on to better things. <strong>Anne McCarthy</strong> is <a href=\"https://nomad.blog/2026/09/24/auctioning-off-my-wordpress-release-albums/\"><strong>auctioning off her framed WordPress release albums</strong></a>, the ones given to release squad members. All the proceeds go to Stimpunks, a nonprofit started by <strong>Ryan Boren</strong>, who joined the project in 2003 and wrote the plugin system that nearly every site runs on. She calls the albums &#8220;a form of a gold medal to me,&#8221; and she built the auction site herself in a week. The starting bid is $500.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also learned this fortnight that the next default theme <a href=\"https://make.wordpress.org/core/2026/09/16/introducing-ipsum-the-new-default-theme/\"><strong>will be called Ipsum</strong></a>, which means 16 years of naming themes after the calendar is over. Admittedly, I&#8217;ll miss the old <em>Twenty*</em> names a little. But it&#8217;s time for something new for a new era.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Two more quick things: WordPress has <a href=\"https://wordpress.org/news/2026/09/owa-president/\"><strong>taken its turn leading the Open Website Alliance</strong></a>, alongside Drupal, Joomla!, and TYPO3, with <strong>Mary Hubbard</strong> holding the rotating presidency for the WordPress Foundation. And starting with 7.2 in December, release parties <a href=\"https://make.wordpress.org/core/2026/09/23/iterating-from-live-events-to-livestreamed-releases/\"><strong>move from in-person events to livestreamed webinars</strong></a>, so the whole squad can actually be there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Enjoy your weekend!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Your friendly neighborhood dev advocate, <img alt=\"🍂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f342.png\" style=\"height: 1em;\" /><br /><em>Justin Tadlock</em></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-b14348ac wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n<nav class=\"wp-block-table-of-contents\"><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-word-press-release-information\">Developing Gutenberg and WordPress</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#ai-in-wordpress\">AI in WordPress</a></li></ul></nav></div>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Two security releases in six days. <a href=\"https://wordpress.org/news/2026/09/wordpress-7-1-2-release/\"><strong>WordPress 7.1.2</strong></a> is the urgent one, and it&#8217;s security-only: an unauthenticated attacker can, under the right conditions, make page template resolution include a readable local PHP file from outside the active theme directories. <strong>John Blackbourn</strong> led the release, <strong>Robert Ressl</strong> disclosed it, and the fix was backported to every eligible branch going back to 4.7.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Five days earlier, <a href=\"https://wordpress.org/news/2026/09/wordpress-7-1-1-maintenance-and-security-release/\"><strong>WordPress 7.1.1</strong></a> arrived as the regular maintenance release with 11 security fixes, 17 bug fixes on Core, and 19 for the Block Editor. <strong>Aaron Jorbin</strong> led it, and Anthropic is credited twice in the security list.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Aki Hamano</strong> announced <a href=\"https://make.wordpress.org/core/2026/09/16/whats-new-in-gutenberg-24-0-16-september/\"><strong>what&#8217;s new in Gutenberg 24.0</strong></a>. The big feature: post title changes now show up in revisions with a proper diff, so you can stop guessing when a rename happened. The Gallery block gains a Grid variation with column count and &#8220;crop images to fit&#8221; configurable per breakpoint, and Site Title picks up fit-text, scaling to the width available instead of a fixed point size. And nearly 100 icons were redrawn on a stroke-based grid.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Stalled out somewhere between &#8220;clone the repo&#8221; and &#8220;why won&#8217;t this build&#8221;? <a href=\"https://make.wordpress.org/core/2026/09/25/wordpress-contributor-toolkit-1-2-one-app-for-your-first-core-or-gutenberg-contribution/\"><strong>Contributor Toolkit 1.2</strong></a> from <strong>JuanMa Garrido</strong> now covers Gutenberg as well as Core, and it runs a stock WordPress in Playground with your checkout mounted as the plugin, already activated. No local server, no Docker.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"the-road-to-7-2\"><strong>The road to 7.2</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Anne McCarthy</strong> published the <a href=\"https://make.wordpress.org/core/2026/09/18/roadmap-to-7-2/\"><strong>roadmap to 7.2</strong></a>, and it looks to be a security-heavy cycle by WordPress standards. Sudo mode gates sensitive admin actions behind re-authentication, a new Secrets API gives credentials &#8220;a first-class way to store credentials safely,&#8221; and Application Passwords get hardened. Notes should gain a suggestion mode and emoji reactions. Designers get form element customization in Global Styles and custom block states. The final release lands in early December.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Real-time collaboration came out of WordPress 7.0, and <strong>Chris Zarate</strong> has now explained why in a post on <a href=\"https://make.wordpress.org/core/2026/09/18/moving-to-a-server-aware-approach-for-collaboration/\"><strong>moving to a server-aware approach for collaboration</strong></a>, written with <strong>Alec Geatches</strong>, <strong>Dennis Snell</strong>, <strong>ingeniumed</strong>, and <strong>Paul Kevan</strong>. The old design had browsers hold the post in a CRDT document and sync peer-to-peer, which broke three ways: the server couldn&#8217;t tell who made which edit, opening the door to content laundering; REST API and WP-CLI updates couldn&#8217;t participate, so saves became all-or-nothing overwrites; and a dropped connection could take your work with it. Three candidate sync engines are on the table, with a gutenberg-sync-engines repo to test against. If you build editorial tooling, have an opinion about this now.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">The next default theme has a name, and for the first time in well over a decade, it isn&#8217;t a year. <strong>Henrique Iamarino</strong> introduced <a href=\"https://make.wordpress.org/core/2026/09/16/introducing-ipsum-the-new-default-theme/\"><strong>Ipsum</strong></a>, built with <strong>Carolina Nymark</strong>, <strong>Maggie Cabrera</strong>, and <strong>Juanfra Aldasoro</strong>. The reasoning behind the naming change: &#8220;default themes will have their own names and change when the design calls for it, not when the calendar does.&#8221; The theme is intentionally spare. It’s blog-first, has minimal typesets, and structural elements that stay invisible until you need them. The request is simple: &#8220;try it and tell us what breaks and what&#8217;s missing.&#8221;</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img alt=\"Screenshot of the Ipsum WordPress theme single post demo, including a Gallery block demo.\" class=\"has-border-color has-accent-5-border-color wp-image-47182\" height=\"1024\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/09/ipsum-single.jpg?resize=1006%2C1024&#038;ssl=1\" style=\"border-width: 1px;\" width=\"1006\" /></figure>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Nik Tsekouras</strong> opened a <a href=\"https://make.wordpress.org/core/2026/09/17/call-for-testing-dataform-editor-inspector/\"><strong>call for testing the DataForm editor inspector</strong></a>, which rebuilds the Post and Page tab of the Settings sidebar so it stops drifting from Quick Edit in the Site Editor. Install Gutenberg 24.0 or later and enable <strong>Editor Inspector: Use DataForm</strong> under <strong>Settings → Gutenberg</strong>. Test it as an editor, author, and contributor, not just as an admin.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"behind-the-release\"><strong>Behind the release</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">A minor release can touch more than twenty branches, and much of that work was done by hand. <strong>Lance Willett</strong> opened a <a href=\"https://make.wordpress.org/core/2026/09/23/new-public-repo-core-release-tools/\"><strong>public repo of Core release tools</strong></a>, which includes tagging, release docs, SVN merge verification, and contributor lists.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Huzaifa Al Mesbah</strong> counted <a href=\"https://make.wordpress.org/test/2026/09/18/thank-you-to-the-wordpress-7-1-test-contributors/\"><strong>84 people who tested WordPress 7.1</strong></a> across 337 Trac tickets. Fifty were first-timers, which is 60% of everyone who showed up. The most important line: &#8220;you don&#8217;t need to be a developer.&#8221; 7.2 testing is open now.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WooCommerce 11.2 lands the week of October 6, so read <strong>Shani Banerjee&#8217;s</strong> <a href=\"https://developer.woocommerce.com/2026/09/21/woocommerce-11-2-0-pre-release-notes/\"><strong>pre-release notes</strong></a> before it arrives rather than after. Order withdrawal emails become configurable, the CSV importer can match products by Global Unique ID when neither ID nor SKU is available, and checkout fields gain date support with min/max validation. Two of the seventeen developer advisories will bite if you ignore them: date filters in <code>wc_get_orders()</code> and <code>wc_get_products()</code> now read a bare date as a day in your store&#8217;s timezone rather than UTC, and the Cart and Checkout order summary becomes a fixed 360px column with the two-column breakpoint moving from 700px to 920px.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Two dot releases arrived in between, both flagged as security updates. <a href=\"https://developer.woocommerce.com/2026/09/22/woocommerce-11-1-2/\"><strong>WooCommerce 11.1.2</strong></a> fixes the infinite recursion that was breaking product variation galleries, and <a href=\"https://developer.woocommerce.com/2026/09/18/woocommerce-11-1-1/\"><strong>11.1.1</strong></a> hardened API permissions and session handling.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">The latest <a href=\"https://wordpress.com/blog/2026/09/15/changelog-custom-ai-themes/\"><strong>WordPress.com changelog</strong></a> moves the AI website builder from picking a theme to generating one: on Premium and Business plans, it &#8220;now generates a fully custom theme built around your goals and brand.&#8221; A new <strong>Annotate</strong> feature lets you queue several targeted edits and send them at once.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">GatherPress started on a fourteen-hour drive to WordCamp US in 2018, when two Montclair meetup organizers came up with a name and then didn&#8217;t write any code for nine months. <strong>Rae Morey</strong> tells the story of <a href=\"https://www.therepository.email/how-gatherpress-grew-from-a-road-trip-idea-to-wordpress-meetup-com-replacement\"><strong>how it grew into WordPress&#8217; Meetup.com replacement</strong></a>, through July of this year, when Automattic&#8217;s <strong>Karen Arnold</strong> confirmed WordPress is going ahead with it. The gatherpress.org domain is transferring to the Foundation, and the plugin has been testable at events.wordpress.org since August 28. No launch date yet, and co-maintainer <strong>Mervin Hernandez Sitnikovski</strong> would rather you help than wait.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WooCommerce has a new block theme. <strong>Brian Coords</strong> announced that <a href=\"https://developer.woocommerce.com/2026/09/15/purple/\"><strong>Purple is back and ready for beta testing</strong></a>. The project was paused during a strategy update last year, and it&#8217;s Woo&#8217;s first official block theme. </p>\n\n\n\n<figure class=\"wp-block-image size-full has-custom-border\"><img alt=\"\" class=\"has-border-color has-accent-6-border-color wp-image-47183\" height=\"1708\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/09/purple-frontpage.jpg?resize=2048%2C1708&#038;ssl=1\" style=\"border-width: 1px;\" width=\"2048\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Ten color palettes, ten font pairings, custom styles for both WooCommerce and core blocks, and templates covering everything from Shop to Checkout to My Account. The inserter category is being renamed from &#8220;WooCommerce&#8221; to &#8220;Shop.&#8221; If you&#8217;re wondering where Storefront&#8217;s featured extensions went, block editing absorbed most of them. <strong>Peter Schimke</strong> also notes that <a href=\"https://wordpress.com/blog/2026/09/16/purple-woocommerce-theme/\"><strong>Purple is now the default for new WordPress.com Commerce stores</strong></a>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Mark your calendar for <strong>Wednesday, September 30 at 10 a.m. PDT / 1 p.m. EDT / 7 p.m. CEST</strong>: Woo is hosting a live session on <a href=\"https://developer.woocommerce.com/2026/09/17/block-theme-event/\"><strong>building with WooCommerce block themes</strong></a>. <strong>Mike McAlister</strong> of Ollie joins Woo engineers <strong>Karol Manijak</strong> and <strong>Lucio Giannotta</strong>. There&#8217;s a Q&amp;A at the end and a recording afterward, but questions only work if you show up.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">&#8220;We need more workflow in Core,&#8221; said <strong>K. Adam White</strong>, principal engineer at Human Made, talking with <strong>Nathan Wrigley</strong> on WP Tavern about <a href=\"https://wptavern.com/podcast/234-k-adam-white-on-migrating-to-blocks-with-artisanal-care-and-enterprise-efficiency\"><strong>migrating to blocks with artisanal care and enterprise efficiency</strong></a>. At the center of it is Human Made&#8217;s open-source <strong>Rehydrator</strong>, which uses pattern HTML as a template and injects migrated content into it, so structure and styling survive a move off something like Sitecore. He describes building SQLite databases from client exports just to find the edge cases. He&#8217;s candid about the gaps, too: granular permissions, editorial approval workflows, and internationalization.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-rich is-provider-pocket-casts wp-block-embed-pocket-casts\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-95352ef4f0c68675 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Your Query Loop returns nothing, and the heading and pagination you wrapped around it render anyway. </em><strong>Ryan Welcher</strong> spent a live stream <a href=\"https://www.youtube.com/watch?v=RaW-0fsXVBM\"><strong>adding a &#8220;hide if empty&#8221; control to Advanced Query Loop</strong></a>, his free plugin that extends the core Query Loop with taxonomy relationships, meta queries, and relative date filters.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Gutenberg&#8217;s JavaScript tests have moved off Jest. <strong>Marco Ciampini</strong> explains that <a href=\"https://make.wordpress.org/core/2026/09/23/gutenbergs-javascript-unit-and-integration-tests-now-use-vitest/\"><strong>unit and integration tests now use Vitest</strong></a>, driven by ESM: as more dependencies shipped ECMAScript modules, the CommonJS-based Jest setup needed more and more compatibility glue. The part that affects you: @wordpress/scripts 36.0.0 makes Vitest the default for test-unit-js, with @wordpress/eslint-plugin 27.0.0 following. Not ready to migrate? Switch to wp-scripts test-unit-jest and install the Jest dependencies yourself.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"ai-in-wordpress\"><strong>AI in WordPress</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Your agent builds you a landing page, and then what? It sits in a chat log, or a folder, or a local dev server nobody else can reach. That&#8217;s the gap <strong>Spacefast</strong> is built for, and Automattic soft-launched it this week: <strong>Matt Mullenweg</strong> <a href=\"https://x.com/photomatt/status/2102877364296257558\"><strong>announced it on X</strong></a>. The pitch is the last mile for agent output: publish from a conversation with Claude or ChatGPT, from <code>npx spacefast publish</code>, or from a GitHub push, and get a permanent URL with immutable versions, one-click rollback, and access controls. It hosts full-stack projects, not just static files.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The WordPress hook is a <a href=\"https://github.com/spacefast/wordpress\"><strong>Spacefast plugin</strong></a> with two modes. Static mode hooks into Simply Static, exports your site, and publishes the snapshot. Headless mode treats WordPress as the content source for a repository project, triggering a production rebuild when you publish or update public content.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"mcp-turns-up-everywhere\"><strong>MCP turns up everywhere</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress Trac now speaks MCP. <strong>Lance Willett</strong> announced a <a href=\"https://make.wordpress.org/core/2026/09/24/wordpress-trac-mcp-server/\"><strong>Trac MCP server</strong></a> that&#8217;s &#8220;public and free to use: no account or API key needed.&#8221; Ask what&#8217;s left on a ticket and which pull requests are still open, or what someone committed in January 2005—<em>yes, it goes back that far</em>. It covers every WordPress.org Trac, from Core and Meta to bbPress and GlotPress. <strong>James LePage</strong> wrote the first version, with props to <strong>Jon Surrell</strong>, <strong>David Newman</strong>, and <strong>Konstantin Obenland</strong>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Jamie Marsland</strong> makes the case for <a href=\"https://www.pootlepress.com/2026/09/why-webmcp-is-going-to-be-big-for-wordpress/\"><strong>why WebMCP is going to be big for WordPress</strong></a> and, more usefully, shows you how to try it this afternoon: open the ChatGPT desktop app in Work mode, load WordPress Playground in its built-in browser, and ask it to build you a homepage. His framing is the clearest I&#8217;ve read. WebMCP gives an assistant &#8220;an instruction manual with working buttons&#8221; instead of making it squint at screenshots.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">For the enterprise view of the same shift, <strong>Shane Schick</strong> compares <a href=\"https://wpvip.com/blog/webmcp-vs-traditional-mcp/\"><strong>WebMCP and traditional MCP</strong></a> and lands on a line I&#8217;d pull out of the whole piece: &#8220;MCP is not going away, and WebMCP shouldn&#8217;t be seen as a rival protocol.&#8221; His table sets them side by side on deployment, access scope, scalability, and auditability. That auditability row is the one that matters if you answer to a compliance team.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Schick also introduces <a href=\"https://wpvip.com/blog/introducing-parse-ly-mcp/\"><strong>Parse.ly MCP</strong></a>, which connects Parse.ly data to whichever assistant your team already uses. You authorize once with your existing login, and the assistant sees exactly the sites your account already sees. &#8220;Analysis that used to take a request and a day now takes a conversation.&#8221;</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">One more, for the security-conscious: WPShout walks through <a href=\"https://wpshout.com/connect-cursor-to-wordpress-mcp/\"><strong>connecting Cursor to WordPress with MCP</strong></a> using ThemeIsle&#8217;s Easy MCP AI plugin. Every tool call still passes a WordPress capability check, with a 60-requests-per-minute default. Their advice is the part to take seriously: &#8220;read-only first, watch the audit log for a week, then grant write scopes deliberately.&#8221;</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"putting-agents-to-work\"><strong>Putting agents to work</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Anthropic open-sourced its commerce agents on September 2, and WooCommerce has already adapted them. <strong>Shani Banerjee</strong> walks through <a href=\"https://developer.woocommerce.com/2026/09/16/wc-claude-commerce-agent/\"><strong>running the Claude Commerce Agent on WooCommerce</strong></a>, which spins up a demo store with eight products and nine orders in about fifteen minutes. The neat piece is a bridge plugin: the assistant&#8217;s cart lives under a Store API token your browser session can&#8217;t see, so at checkout the plugin re-adds each item to your real cart with normal stock checks. Merchant-side changes stage behind an approval gate, and &#8220;ask it to approve itself and it declines.&#8221;</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s a second kind of visitor to design for now. <strong>Carlo Daniele</strong> argues for <a href=\"https://kinsta.com/blog/wordpress-for-ai-agents/\"><strong>building WordPress for AI agents instead of just human visitors</strong></a>, and the distinction he draws is the useful one: &#8220;Crawlers primarily retrieve or index information. Agents can go a step further and take action on a user&#8217;s behalf.&#8221; That turns architecture questions into permission questions: who is asking, on whose behalf, what can they change, which actions need approval. The Abilities API and MCP Adapter are where WordPress answers them.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">A week later, Daniele turned to operations. <a href=\"https://kinsta.com/blog/ai-wordpress-operators/\"><strong>What happens when AI agents become your new website operators?</strong></a> works through a five-stage autonomy ladder and argues most teams should sit partway up it for a while. I feel like he&#8217;s right about that. As he puts it: &#8220;An agent that makes a bad production change creates another.&#8221;</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"learning-and-practice\"><strong>Learning and practice</strong></h3>\n\n\n\n<p class=\"wp-block-paragraph\">Want a structured introduction rather than a pile of blog posts? <strong>Destiny Kanno</strong> announced that the <a href=\"https://make.wordpress.org/ai/2026/09/18/xpost-the-ai-powered-wordpress-course-is-now-live-on-learn-wordpress/\"><strong>AI-Powered WordPress course is now live on Learn WordPress</strong></a>: four modules, 23 lessons, roughly nine hours. The first three are for anyone who publishes; the fourth introduces the developer APIs and assumes no prior PHP experience.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">The AI team&#8217;s <a href=\"https://make.wordpress.org/ai/2026/09/16/ai-contributor-weekly-summary-16-september-2026/\"><strong>contributor summary for September 16</strong></a> is a good snapshot of what&#8217;s actually moving. <strong>neillmcshea</strong> reports work on markdown feeds for the AI plugin, so AI clients can request a markdown version of a post. PHP AI Client 1.5.0 is close. There are still open gaps in web search support. For example, message parts can&#8217;t represent source annotations, and citation URLs are hard to retrieve.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Finally, a piece for the conversations you have with clients rather than with a terminal. <strong>Will Davis</strong> writes about <a href=\"https://humanmade.com/ai/how-wordpress-agencies-use-ai-and-what-clients-should-ask/\"><strong>how WordPress agencies use AI, and what clients should ask about it</strong></a>, arguing that the honest uses are the boring ones—code generation, QA, content migration, documentation—while architecture and governance stay human. His five questions for clients would work just as well on a sales call, starting with &#8220;What does a person review before it reaches me?&#8221; As he puts it, AI &#8220;genuinely reduces repetitive work, but it doesn&#8217;t replace judgment.&#8221;</p>\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-7488c8b3cd5762fc wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--1\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-450a8e6b4d7c807e wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--2\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 26 Sep 2026 16:45:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Justin Tadlock\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"Dennis Snell: Enter the mess: Shortcodes\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"https://fluffyandflakey.blog/?p=4130\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"https://fluffyandflakey.blog/2026/09/25/enter-the-mess-shortcodes/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1005:\"<p class=\"wp-block-paragraph\">Tonight I started working on some Shortcode processing in WordPress. This is an historically nasty problem because the Shortcode syntax and parsing is wildly dynamic.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Shortcode syntax is only technically recognized for shortcodes registered at the time of parsing. This means that there is not a general Shortcode grammar.</li>\n\n\n\n<li>Whether a shortcode has “content,” meaning whether it expects a closing tag, depends on whether the closing tag <em>exists</em> in the post.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">This is a problem that has plagued me for years and I have generally just ignored. There’s an open Core issue in Trac for changing some shortcode parsing (<a href=\"https://core.trac.wordpress.org/ticket/50683\">#50683</a>), and I have thought a lot about it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I think there is more to explore, and more to gain. Maybe this goes nowhere, but keep your eyes open for it.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 26 Sep 2026 02:43:45 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Dennis Snell\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"Open Channels FM: Your Website Could Use a Changelog to Fuel Creativity\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562622\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"https://openchannels.fm/your-website-could-use-a-changelog-to-fuel-creativity/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:220:\"A website changelog helps creators document progress, celebrate small wins, showcase evolution, fuel creativity, and build audience trust. It can include updates, humor, and various formats, making it accessible for all.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 25 Sep 2026 13:44:23 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:94:\"Open Channels FM: Is It Time to Move On?  Navigating Change and Letting Go in Fast-Paced Times\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562603\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:99:\"https://openchannels.fm/is-it-time-to-move-on-navigating-change-and-letting-go-in-fast-paced-times/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"A reflection on recognizing the right time to move on from creative projects and handling self-doubt.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 25 Sep 2026 12:30:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:100:\"OpenStation Blog: “I can’t imagine using WordPress any other way”: the love behind OpenStation\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://openstation.blog/?p=1306\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:109:\"https://openstation.blog/2026/09/25/i-cant-imagine-using-wordpress-any-other-way-the-love-behind-openstation/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:8731:\"<figure class=\"wp-block-image size-large\"><img alt=\"A digital workspace interface displaying various applications, including a note-taking feature, recent comments section, and post statistics, alongside a scenic background featuring a rider on horseback in a vast landscape.\" class=\"wp-image-1308\" height=\"568\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/HS_NADgXsAABwZg.jpeg?resize=1024%2C568&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>OPENSTATION · COMMUNITY VOICES</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Formerly Desktop Mode, now a new way to feel at home in wp-admin.</em></p>\n\n\n\n<p class=\"wp-block-paragraph\">A plugin can accumulate installs. It is rarer for people to describe it as a new way of thinking. As of September 25, 2026, OpenStation, known in its earliest releases as Desktop Mode, has inspired <strong>23 public WordPress.org reviews: 22 five-star and one four-star</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">OpenStation turns the WordPress admin into a spatial workspace: movable windows, a dock, a taskbar, widgets and virtual desktops. That is the feature list. The feeling is better told by the people who use it.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\">The words that stopped us in our tracks</h2>\n\n\n\n<h3 class=\"wp-block-heading\">1. When a plugin becomes the default</h3>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“I can’t imagine using WordPress any other way. I love this plugin so much.”</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>— Nick Hamze, <a href=\"https://wordpress.org/support/topic/favorite-plugin-ever-2/\">“Favorite plugin ever”</a></em></p>\n\n\n\n<p class=\"wp-block-paragraph\">That may be the highest compliment a tool can earn: not merely useful, but difficult to imagine living without. Nick’s review reads less like a rating and more like an invitation to join a movement.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“This is a game-changer. Can never go back!”</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>— ainom, <a href=\"https://wordpress.org/support/topic/absolute-pure-awesomeness/\">“Absolute pure awesomeness”</a></em></p>\n\n\n\n<p class=\"wp-block-paragraph\">OpenStation begins as a striking visual idea, then quietly rewires expectations. Once several admin screens can live together, the old one-page-at-a-time flow feels surprisingly distant.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\">2. When the metaphor improves the work</h3>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“It genuinely feels like using a lightweight operating system inside WordPress.”</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>— spackenjaeger, <a href=\"https://wordpress.org/support/topic/a-revolutionary-new-wordpress-admin-experience/\">“A revolutionary new WordPress admin experience”</a></em></p>\n\n\n\n<p class=\"wp-block-paragraph\">The operating-system metaphor is not decoration. Windows hold context. The dock makes tools reachable. Virtual desktops separate kinds of work. The familiar desktop grammar turns multitasking into something visible and natural.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“Having several admin screens open at once changed how I work more than I expected.”</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>— Juan Lentino, <a href=\"https://wordpress.org/support/topic/renamed-its-entire-public-api-without-breaking-a-single-integration-point-2/\">production user and plugin integrator</a></em></p>\n\n\n\n<p class=\"wp-block-paragraph\">Juan’s review is especially telling: he has run OpenStation in production since the Desktop Mode days and builds integrations against it. The novelty faded; the workflow remained.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\">3. When delight becomes productive</h3>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“The desktop-style layout, draggable windows, dock, and taskbar make the admin area feel completely different in the best way.”</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>— Marco Moreira, <a href=\"https://wordpress.org/support/topic/a-refreshing-new-way-to-use-wordpress-admin/\">“A refreshing new way to use WordPress admin”</a></em></p>\n\n\n\n<p class=\"wp-block-paragraph\">Productivity software does not have to be joyless. The best interfaces reduce friction and add a little momentum, the feeling that the workspace is helping rather than merely waiting.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“This plugin blowed my mind. It turns your wordpress admin in such a beautiful dashboard. What an experience.”</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>— MauroS, <a href=\"https://wordpress.org/support/topic/one-word-wow-7/\">“One word… Wow!”</a></em></p>\n\n\n\n<p class=\"wp-block-paragraph\">The wording is wonderfully unfiltered. Beauty, surprise and experience are not side effects here; they are part of the product.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h3 class=\"wp-block-heading\">4. When people see the road ahead</h3>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“This is definitely something I would use on a daily basis. Well done!”</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>— vepth, <a href=\"https://wordpress.org/support/topic/im-blown-away-3/\">“I’m blown away”</a></em></p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“Desktop Mode definitely stands out with its own approach.”</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>— Rami Obeidat, <a href=\"https://wordpress.org/support/topic/modern-and-creative-admin-experience/\">“Modern and creative admin experience”</a></em></p>\n\n\n\n<p class=\"wp-block-paragraph\">Both reviews point to the same achievement: OpenStation is not chasing a generic “modern admin” look. It has a point of view—spatial, extensible and unmistakably its own.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\">From Desktop Mode to OpenStation</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The project’s name changed because its ambition outgrew a mode. “Desktop Mode” described the first transformation. <strong>OpenStation</strong> describes the platform emerging around it: a place where WordPress apps, windows, widgets and workflows can meet.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“The integration surface is unusually well behaved for a plugin this ambitious.”</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><em>— Juan Lentino, <a href=\"https://wordpress.org/support/topic/renamed-its-entire-public-api-without-breaking-a-single-integration-point-2/\">WordPress.org reviewer and integrator</a></em></p>\n\n\n\n<p class=\"wp-block-paragraph\">That sentence matters as much as the praise for the interface. The magic users see is supported by a public API that plugin authors can build on, frequent releases and an opt-in design that keeps classic WordPress one click away.</p>\n\n\n\n<h2 class=\"wp-block-heading\">The best roadmap is a chorus</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Names change. Interfaces evolve. Code ships, breaks, improves and ships again. What stays constant in these reviews is the feeling that WordPress can be more personal, more spatial and more alive.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>OpenStation is still moving fast.</strong> But if the people already living in it are any guide, the destination is worth watching, and the journey is already changing how they work.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://github.com/WordPress/openstation\"><strong>Explore OpenStation on GitHub →</strong></a><br /><a href=\"https://wordpress.org/support/plugin/desktop-mode/reviews/\"><strong>Read all WordPress.org reviews →</strong></a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><small>Quotes are excerpted from public WordPress.org reviews. Spelling is preserved; excerpts are linked to their original sources.</small></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 25 Sep 2026 11:33:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Daniel López\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Matt: Bruce Schneier on Systems\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155048\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://ma.tt/2026/09/schneier/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:460:\"<figure class=\"wp-block-embed alignwide is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Bruce is one of my favorite writers. He packs profoundness. Also honored that he&#8217;s an advisor at <a href=\"https://automattic.com/\">Automattic</a>, truly one of my idols. His blogs and books rocked my world when I was young.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 25 Sep 2026 07:04:50 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:76:\"Open Channels FM: How Generational Perspectives Shape Our Digital Work Lives\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562342\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"https://openchannels.fm/how-generational-perspectives-shape-our-digital-work-lives/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:114:\"Cami and Bob talk about adapting to tech changes growing older in the web industry and keeping routines that work.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 24 Sep 2026 14:30:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:109:\"Open Channels FM: Navigating Support Systems from the Man Cold to Open Source and WordPress Open Web Alliance\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562536\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"https://openchannels.fm/navigating-support-systems-from-the-man-cold-to-open-source-and-wordpress-open-web-alliance/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:132:\"Examining support systems behind open source, the open web, and everyday life, along with why sustaining these efforts is necessary.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 24 Sep 2026 13:02:50 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"Open Channels FM: The Podcast Open Makers is Archived\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562154\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:60:\"https://openchannels.fm/the-podcast-open-makers-is-archived/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:221:\"The podcast network has reduced its active lineup to four shows, leading to no new episodes for Open Makers. However, past content remains accessible, with a shift towards deeper discussions on open source and web trends.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 23 Sep 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"WPTavern: #234 – K. Adam White on Migrating to Blocks With Artisanal Care and Enterprise Efficiency\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=208362\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:114:\"https://wptavern.com/podcast/234-k-adam-white-on-migrating-to-blocks-with-artisanal-care-and-enterprise-efficiency\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:53882:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, migrating to blocks at an enterprise level and what&#8217;s involved in moving from a different CMS into WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today, we have K. Adam White, or K. Adam for short.  K. Adam is the principal engineer at Human Made, an enterprise WordPress consultancy. He&#8217;s been involved with WordPress for almost 20 years, attending his first WordCamp in Boston back in 2011, and has contributed to WordPress Core and the broader open source ecosystem. Human Made is known for delivering complex projects, think high stakes, no room for mistakes? From global brands moving to WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This time around,  K. Adam delivered a presentation at WordCamp US focused on a crucial topic for anyone modernising their site, migrating to blocks. Human Made has been all in on the block editor since the Gutenberg plugin days, and the team now specialises in large scale migrations from other content management systems like Sitecore, as well as from other WordPress page builders.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our conversation focused on the technical and editorial challenges of moving tens, or hundreds, of thousands of posts into the world of blocks and patterns. We talked about the need to combine artisanal care, attention to detail in design, layout, and brand, with industrial scale. The ability to automate, audit and validate mass migrations without losing visual fidelity.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also discussed the use of patterns as a foundation for development, integrating custom and Core blocks, and leveraging new tools, including AI powered agents and open source plugins like Human Made&#8217;s, own rehydrator, to streamline migration workflows.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also touched upon how clients are onboarded. The process of auditing legacy content. Strategies for training editorial teams on the block editor. And there&#8217;s a frank reflection on gaps in WordPress, like granular content permissions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you are contemplating a move to the block editor, wrestling with a massive content migration, or curious about what happens when enterprise complexity meets the flexibility of WordPress, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you  K. Adam White.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by K. Adam White. Hello, K. Adam.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:41] <strong>K. Adam White:</strong> Hello. It&#8217;s good to be here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:42] <strong>Nathan Wrigley:</strong> Yeah. Thank you for joining us. You have an interesting name. Just go on, I know it&#8217;s totally off piste, but tell us about your name.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:49] <strong>K. Adam White:</strong> Sure. It&#8217;s a first initial K, and the middle name Adam that got conjoined in college and I quite like it. So I think in a sphere, and a particular niche in WordPress with so many Adams of so many different colours, then K. Adam is a little bit more me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:04] <strong>Nathan Wrigley:</strong> Yeah, nice. So we&#8217;re in the corridor, so forgive any noise that you hear on this podcast episode. We can&#8217;t avoid it. We&#8217;re in the corridor at  WordCamp US, and you have done, some presentation work this time around. Do you want to just tell us, I mean I presume it&#8217;s happened because we&#8217;re at the very closing stages of the conference. How did it go?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:21] <strong>K. Adam White:</strong> It went, as far as I can tell, quite well. My session was early yesterday, right after the morning keynotes in that early slot where everyone&#8217;s coffee has kicked in, and the fatigue of the conference hasn&#8217;t quite set in yet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I had a great audience and the talk I thing went quite well. I&#8217;ve had a number of different conversations off the back of it on various different topics that I covered. So the breadth of those discussions has been really exciting for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:44] <strong>Nathan Wrigley:</strong> So that is going to be the meat and the bones of what we&#8217;re going to talk about today. But first, if you don&#8217;t mind, let&#8217;s talk a little bit about you and what you do and where you work, just so that we can paint your credentials if you like.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So tell us about your job, how long you&#8217;ve been in the WordPress space? Who do you work for? Et cetera.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:59] <strong>K. Adam White:</strong> Yeah. My job is principal engineer at Human Made. We&#8217;re a WordPress enterprise consultancy, and I have been there nine years. I&#8217;ve been in the WordPress community quite a lot longer than that. My first WordCamp was WordCamp Boston 2011, which is a mind boggling 15 years ago now. And before that, I had been using WordPress personally since 2007. So we&#8217;re coming up on 20 years of involvement, at least as a user. And then, became a contributor in the early 2010s around 2013, I think my first commit landed.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:25] <strong>Nathan Wrigley:</strong> Yeah, nice and Human Made, if you haven&#8217;t heard, we&#8217;ll put the links into the show notes, anything that K. Adam mentions today, we will put us a link on the WP Tavern podcast episode website, so you can click through to it. But go and check out Human Made, definitely one of the big hitters. I think it&#8217;s fair to say in the WordPress space.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:40] <strong>K. Adam White:</strong> It&#8217;s very kind of you to say so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:42] <strong>Nathan Wrigley:</strong> You did your presentation and it was entitled, Migrating to Blocks. I&#8217;m going to intuit from that, that Human Made is all in on the block editor. You&#8217;re not using some sort of other proprietary platform. Would that be the case?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:55] <strong>K. Adam White:</strong> That would be the case. We were very early adopters of Gutenberg back in its plugin days. We were doing work before it was merged for building out some early block sites, testing out what we could do. Learning how to build and change our theme development processes to move in a more block oriented direction, and then follow that directly into the Full Site Editor world.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And it&#8217;s been a great ride. We do work with other page builders and other blocks, platforms and frameworks. We do tend to, as a company, work on projects that have some sort of particular technical complexity that made someone come to us rather than a different agency.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That does mean that we are broadly specialised in WordPress as a platform, including many of those page builders. We&#8217;ve worked with Elementor, we&#8217;ve worked with Divi, Beaver Builder, but we as a company will always advocate for the block editor and the site editor. And we have our own processes oriented more and more towards delivery with that framework in mind.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think that the thing that is bringing some of the companies that we help to migrate to WordPress into this ecosystem is the flexibility and the quality of the editorial experience. And personally, my opinion is that Gutenberg does that leaps and bounds better than any of our other page builders that don&#8217;t have that native integration into the platform.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:09] <strong>Nathan Wrigley:</strong> So if a client comes to you and they are agnostic as to what you are going to build with, your default posture would be we are going to use the block editor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:16] <strong>K. Adam White:</strong> Absolutely default.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:17] <strong>Nathan Wrigley:</strong> Okay. And do you have to do any level of persuasion anymore? I&#8217;m guessing if we were to rewind the clock, let&#8217;s go to 2017, soon after Gutenberg started to become more widely available. I imagine there was quite a bit of explaining to do. Do you still have to do any of that? Or is it a case now that the enterprise people understand what&#8217;s going on, and there&#8217;s less of a back and forth about whether they should use blocks and patterns and whatever else?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:41] <strong>K. Adam White:</strong> If we are building from scratch, we haven&#8217;t found there is any reluctance. Particularly if people are coming from a different content management system, particularly a different enterprise content management system. The editor is so compelling, that there&#8217;s never any objection to using it. They might ask, should we use this or some other thing I&#8217;ve heard of? And we can say, the block editor is built in. We feel that it&#8217;s the most robust and future proof platform that you can choose. So we would recommend going that route rather than adding in another plugin, however good they are.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But we do still, nonetheless, have some projects where they are already on a page builder, and they might have invested a lot of training. We might have an entire business school worth of people that are very comfortable with whatever their existing system is, whether that&#8217;s Beaver Builder or something else, et cetera, Elementor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think that it&#8217;s very important for us to remember what our remit is when we come into a project. That, doesn&#8217;t always involve helping them change everything to match what we see as the future. I think that&#8217;s a responsibility of the client to understand where they are in conjunction with where the WordPress roadmap is, and make their own decisions about what tools are right for them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, for existing projects, we&#8217;ll work with what&#8217;s right for the clients editorial team, but if we have to make a recommendation, it will always be the block editor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:56] <strong>Nathan Wrigley:</strong> Okay. Yeah, good to know. At place in the market where you are, I&#8217;m presuming there&#8217;s very little room for error. When you build something, it&#8217;s got to work out of the box, on day one. You&#8217;ve presumably got stakeholders who&#8217;ve got editorial teams, and they&#8217;re fairly, we&#8217;re, dealing with large corporations that can&#8217;t afford for there to be mistakes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that kind of leads us to the nature of your presentation, which was called, and again, links will be in the show notes on wptavern.com. Migrating to Blocks with Artisanal Care and Industrial Scale. And I&#8217;m actually just going to read the first paragraph because it summarises what we&#8217;re going to talk about perfectly. It&#8217;s fairly long, but I&#8217;ll go through it all.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Whether we&#8217;re modernising an old personal blog or migrating hundreds of thousands of existing posts from another CMS. Using WordPress in 2026 means converting our contents to blocks. The convert to blocks button in the editor works well enough for one post. But if we have dozens or hundreds, what can we do to make the process less manual and more powerful? How can we integrate a site&#8217;s content directly into full block patterns without losing the columns and structure it had before? And then it goes on to mention, a particular build, I presume, where you were leaving one CMS coming into WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Just lay out some of the fun, interesting problems that you have to overcome when you&#8217;re moving from an entirely different CMS into WordPress, because I guess it&#8217;s more complicated than, &#8220;Look, there&#8217;s a bunch of paragraphs and images. Let&#8217;s just drag those over and hope for the best.&#8221; Tell us what the problem before you is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:22] <strong>K. Adam White:</strong> That&#8217;s a great question. It&#8217;s actually remarkable how close you can get to satisfaction with just moving paragraphs and images over and hoping for the best. But there is a big gap in terms of visual fidelity.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The editor in a theme that we&#8217;ve built for a client will be configured with patterns and templates and all of the block variations that they need to be able to very quickly sketch out a page. If they are starting from scratch, a client with a fully site editing enabled theme can drop a hero pattern on the page, set in the media they need. Change any font sizes within the pallet of what&#8217;s available with their brand guidelines encoded in the theme.json. It&#8217;s very easy for them to build out and write content fresh.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But if you have, again, hundreds of thousands of posts, even if you&#8217;ve built all those patterns, the heading and paragraph and image only approach doesn&#8217;t cut it, because then there would be a tremendously backbreaking amount of work, adding group blocks, adding background colours, et cetera.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That&#8217;s usually data that is available in one form or the other in the current system. If we&#8217;re migrating without a design change, we will have, whether it&#8217;s the layout database in Sitecore or a metadata in a different WordPress block editor that we&#8217;re migrating from. Or whatever the equivalent is in our source. We want to preserve the layout of the page and the styling elements. So making sure that headings get the right text treatment, that anything that&#8217;s italicised comes over. All of the nuances there, particularly around background colours, images, et cetera. That&#8217;s the piece that we&#8217;ve been over the past year, looking at how we can improve our process when we&#8217;re building a new site, but bringing content over from an old.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Within that context, my talk covered two broad areas. The specific tail end of the talk was about how we can actually use the theme patterns that already exist in the theme directory, and use those to inject particular pieces of source data. So if you have a pattern for a hero element, and you know from your source data what the image URL is supposed to be, what the title is supposed to be. We can use the HTML directly from the pattern file, and do lightweight search replaces within that using either direct PHP string replacements or a tool that we&#8217;ve written, that I shared a link to called rehydrator, which is a very early stage experiment, that we&#8217;ve got out on GitHub.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And we can use that to put the content into the structure that it&#8217;s going to need to have for it to be fully, visually correct. So rather than just reducing and throwing away anything that isn&#8217;t a heading or a paragraph, we&#8217;re taking the framework from the theme pattern that&#8217;s been built. And then we&#8217;re writing a migrator that takes data and puts it into that HTML structure, and saves that into the post content. So that when an editor opens up a page, it loads correctly in the editor without block validation errors and it looks right on the front end.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:15] <strong>Nathan Wrigley:</strong> Okay. There&#8217;s a lot of depth in that, isn&#8217;t there? We&#8217;ll come back to that in a moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m curious about process of how you, persuade clients that you are going to be able to carry this work out successfully. So how does that actually work? You obviously look at their existing content, you have a discussion about what the new design is going to look like, and then do you build out some kind of templates or patterns or what have you, so that you can then pull in a proportion of the content, maybe, I don&#8217;t know, 10 or a hundred or 5,000 or whatever it may be, pieces of content. Check that that&#8217;s all right. Show it to the client. How does that workflow go to build up their confidence that what you are going to do when you finally click the button is actually going to succeed?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:50] <strong>K. Adam White:</strong> The way that we&#8217;ve been approaching that, I think particularly, over the past six months, I should caveat first that this process has changed so much. Because the tools we have available with AI agents have been evolving in leaps and bounds alongside this particular migration process, which started in January.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So in this case, we started out by building patterns that we could put content for one test post, from the existing site manually. Bringing the contents over, copying and pasting headings, et cetera. And using that to create the patterns that we could show to the client to say, does this look correct? Does this structure mirror what you&#8217;re expecting? Is this what you expect an author to have available within the post editor?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then you know, which pieces belong in the template, which pieces are managed at the site editor level? We&#8217;ve done a lot of that ahead of starting the actual migration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now that the migration is in progress, any subsequent pieces we&#8217;re developing in tandem, we&#8217;re saying, okay, we have a press release. That press release, we have audited the incoming data, and we have determined that there are four different layouts for press releases. And this one is used the most and it has these elements. This one is used less, but it has images, et cetera.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And we can build the template for that post type, and at the same time write the migrator for identifying the content nodes, and the source data and bringing that information over into the new patterns.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So we have the patterns that we can show, okay, if you&#8217;re building something from scratch, this is what that looks like in the editor. But then at the same time, we can run the migrator over, in most cases, all of the relevant type of data and say, and here is a list of pages to validate.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So what we&#8217;ve been doing is bringing that to our stakeholder, and allowing them to do spot checks, so that they can look through and validate that there are all of the required elements on the test pages. Things like, &#8220;oh, alright, we don&#8217;t have a mapper yet for video embeds. So videos are missing,&#8221; and that&#8217;s usually going to be an all or nothing thing. We&#8217;ve found very few cases where we end up with one or two errors on a specific post basis that aren&#8217;t related to support for a complete type of output pattern.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:55] <strong>Nathan Wrigley:</strong> Is there a sort of fault tolerance there? So obviously in the case of this particular migration, tens of thousands of posts, I guess there&#8217;s never going to be a moment where you can be a hundred percent confident apart from reading the 10,000 posts that you&#8217;ve done everything correctly. Is there a, we&#8217;ll do 10 to begin with, then we&#8217;ll go up to a hundred, then we&#8217;ll go up to a thousand.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What, is the sort of tolerance that you present to the client? I&#8217;m just imagining that just lurking in post 9,999 is just some weird thing that was allowable in the CMS but never got used before or since, and that piece of content got missed. I don&#8217;t know what&#8217;s allowable in that scenario. So is there any level of tolerance for fault?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:32] <strong>K. Adam White:</strong> The major advance that we&#8217;ve made with migrations as a broad structure this year is a much better understanding of those edge cases. And the way that we&#8217;ve done that is by leveraging Claude and various other tools to do cross site audits to make sure that we have a full picture of the source data.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So we are able to feed in whatever export files we get from our source site. In this case we&#8217;re working from Sitecore, which is an enterprise CMS, which has two database structure. There&#8217;s actually a database with a content tree, and then another database that contains layout information. And a page is rendered by switching back and forth between those and assembling the final output.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We were able to get exports of the relevant content from both of those, from the developer of the current site. And we fed those and a whole bunch of documents from the product owner into a ongoing conversation with Claude. And we&#8217;re able to use that to build some actually node.js scripts that would take the files we&#8217;d gotten from the Sitecore devs, and build a local database in SQLite that each developer on the team was able to run locally. And we can query against that to find those edge cases.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So in a combination of writing our own manual queries, or having a chat conversation prompt for finding individual things, and then it will run a number of queries and report back to us. We&#8217;re able to identify very quickly, oh, there&#8217;s only one press release that has images, that&#8217;s interesting. But there are 17 that have a FAQ accordion.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that type of auditing has become trivial, and it&#8217;s mind boggling how much faster that&#8217;s allowed us to move in terms of understanding the data that&#8217;s there, and building out a mapping of how we&#8217;ll migrate through the different types of content.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We don&#8217;t tend to start with only 10 pages in a post type because it&#8217;s relatively cheap to run the migrator over a thousand instead of 10. And that gives you a lot more content for both various people on the client team, but then also agentic tools to click through and do a little bit of spot check validation.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What we tend to do is to migrate content type by content type, and we&#8217;ll prioritise those based on what we see as the balance between scale and complexity.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:39] <strong>Nathan Wrigley:</strong> Do you leverage Core blocks wherever possible, or do you bring bespoke Human Made blocks where that&#8217;s necessary? Or can you basically bind everything in this particular build to a Core block?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:51] <strong>K. Adam White:</strong> Most of the time we will start with Core blocks and get as far as we can with them. This is a change from how we used to do it. Our early days, we had a lot of rapid iteration in the markup that Core blocks were using. In some cases, there was a lot of evolution in how the controls for them were set up.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:07] <strong>Nathan Wrigley:</strong> It was brutal.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:09] <strong>K. Adam White:</strong> It was brutal. But that pace of change for the main building blocks of a site has slowed down tremendously, and I think it&#8217;s a very stable foundation. So we will be pattern first in our development. We will start by working, doing a lot of in-editor prototyping actually, to build out layouts and patterns for each individual unit of content, each individual sort of component group in the source site. And, it will only be when we run into something like a carousel or a modal that we might reach for a off the shelf, third party option that&#8217;s not in Core, or bring our own solution to the table.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:45] <strong>Nathan Wrigley:</strong> So do you take, when you said pattern there, is a pattern a sub component of a, let&#8217;s say post for want of a better word? Or is it that the pattern is the entire post with bits injected into it? So paragraphs, headings, videos, whatever it may be? Like I said, at the beginning, or are you building up the entire post from various different patterns? Here&#8217;s a video pattern and here&#8217;s a, I don&#8217;t know, a paragraph pattern with a heading? Or a background image or whatever it may be.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:12] <strong>K. Adam White:</strong> Patterns tends to be at number of different levels. We might have individual patterns for a particular treatment of headline for example. But we also will have a pattern for a hero section. We&#8217;ll have a pattern for a hero section plus the bio below that, that we can use to populate a template in the site editor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We build patterns at multiple levels of granularity, and we have a leaf to trunk system where we&#8217;ll make sure that we have renderings, whether they&#8217;re Core blocks with either default styling or one or two block variations, or individual patterns for things where we need to compose one or two blocks together. We&#8217;ll make sure that we have all of those leaf node pieces of content, all of our paragraphs, all of our inline images. And then we&#8217;ll build patterns for those higher level groups, the full width backgrounds with coloration and a particular headline treatment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We build out those patterns at all of those different levels because it&#8217;s nice to have the granularity when we&#8217;re writing our migrators, and patterns can reference each other. So you can have an accordion pattern, which includes two references to an accordion item pattern, and you can have all of those little bits of HTML be discreet PHP files in your WordPress theme. So it makes it very simple to pull up in your editor only the code that you need to edit for a particular unit and know how that&#8217;s going to be scoped.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:26] <strong>Nathan Wrigley:</strong> This is going to sound like such a peculiar question, but it genuinely, from my point of view, this sounds like really interesting and curious work. It sounds, like there&#8217;s a lot to get your teeth into. You&#8217;re pushing the boundaries a little bit, but also you&#8217;ve got the scope of WordPress, which kind of makes it slightly easier.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m basically just making the comment that I think I would enjoy doing the work that you are doing. I don&#8217;t know if that, yeah, there really a question there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:47] <strong>K. Adam White:</strong> Unfortunately, we&#8217;re doing less and less of that work, and Claude&#8217;s doing more and more of it. It&#8217;s been actually very efficient because this is such a core central construct in the WordPress block editor. There&#8217;s a lot of good documentation about it and agentic tools are quite good at helping to build pattern markup.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, what we&#8217;ve been doing is bringing our human eyes onto that, doing all of our spot checks, making sure that things are kept as simple as possible. Because I think we&#8217;re all familiar with how verbose and overly complicated output can be from some tools. But then it is also something that I really wish more people were talking about and doing. Brian Coords earlier today in his talk, mentioned that pattern driven development really he sees as something that more and more of the WordPress community should be trying out. Because there are so many things that we used to build custom blocks for, that just strictly aren&#8217;t necessary anymore. And we can get so far by composing what we get from the lego kit of WordPress out of the box.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:40] <strong>Nathan Wrigley:</strong> Yeah, I feel like if we went back to 2015 and began Gutenberg again, I feel going patterns first would actually be a nicer approach, certainly a more straightforward approach. I know that there&#8217;s, ways to overcome that, but I always drop patterns in, never blocks, and then I&#8217;m always interacting with the blocks within the pattern. But it&#8217;s patterns first for me all the time. Just because I like the fact that I&#8217;m dropping in multiple bits of content that are pre-configured and pre-made and pre, I&#8217;ve fiddled with the CSS and made it just how I like it. And I just click the button once and there it is, and I can just rinse and repeat and it&#8217;s really straightforward.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:12] <strong>K. Adam White:</strong> I would agree, and over the past two to five releases of WordPress, we&#8217;ve also had such powerful additional tools added to the pattern toolkit. For example, Partially Synced Patterns. Was a major topic that I shared in my talk. Being able to have a reusable pattern and then make the content editable on a post by post basis makes it very seamless for a non-technical editor to go in, and not have access out of the box to stylistic controls that would make something drift from the brand&#8217;s guidelines that they&#8217;re trying to follow, but still be able to customise link targets, CTA, text, all of the descriptive and image elements.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:47] <strong>Nathan Wrigley:</strong> You are in the weeds of WordPress, and I&#8217;m in the weeds of WordPress all the time, but I still feel those tools are widely, not misunderstood, that&#8217;s the wrong, just there&#8217;s a void. Nobody even knows they&#8217;re there. There&#8217;s just tonnes of tooling inside the block editor that people simply don&#8217;t know about, because the UI and the UX is still a bit funky. You&#8217;ve got to go to various different places, and it&#8217;s easy to go down the wrong route.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do you know what I mean? There&#8217;s a bunch of tools inside a WordPress that if you only had a few hours with somebody over your shoulder pointing out, &#8220;okay, click on that, look at that menu that does this thing.&#8221; It&#8217;s a shame in a way that&#8217;s the case. But I do feel there&#8217;s a lot of unexplored potential in every WordPress website that presumably you are leveraging. But I guess just because you&#8217;re in the weeds of it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:30] <strong>K. Adam White:</strong> Wherever possible, we have the privilege of having a lot of history with the CMS. Human Made was founded in 2010 and has always had a strong open source posture. We&#8217;ve contributed to Core, we&#8217;ve put plugins out there in the ecosystem that are used by a number of other agencies. We&#8217;ve found the best of what our frenemy competitors use, and been able to adopt those into our own processes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the benefits of understanding all of the different types of block that you can use tremendously outweigh any time sink that it takes to learn them. I hope that, from my talk, people will now know that in 7.0, we added PHP only blocks, where you can have the attributes auto registered so that you get, even as a non JavaScript developer, a interface in the editor that someone can open up and go in and change values in the sidebar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I hope that more people learn about Partially Synced Patterns. I hope more people learn about all of the different types of block that we have available, and find ways to integrate those into their own toolkits. Because playing with the grain of WordPress and using the Block Editor for all it&#8217;s worth, are how we untap the most value for our clients.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:34] <strong>Nathan Wrigley:</strong> Yeah, there is certainly an awful lot of power, and like I said, I just think some of it gets missed.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How much after you&#8217;ve done the migration, how much time do you have to spend with the clients? I have this impression that the Gutenberg editor is pretty straightforward, muscle memory for me essentially. Hours of playing in it. I know where all the bits and pieces are.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I would also recognise that if I was to show it to somebody who&#8217;d never played with WordPress and was coming from, in this case Sitecore, how overwhelming is it? And do you take steps to make it less overwhelming by minimising what&#8217;s available in the interface, or just disabling options? What do you do in that regard?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:08] <strong>K. Adam White:</strong> No matter how much flexibility our clients want, it&#8217;s usually valuable to disable some options. I can&#8217;t remember a site we&#8217;ve shipped recently for any large website where we left the custom colour picker in, for example. You want to do a better job of limiting what people can use, so that we have confidence that the output, no matter how design savvy or not someone is, is going to be consistent with the rest of the site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My colleague, Joeleen Kennedy, gave a talk a couple years ago at the first  WordCamp US Showcase Day back in 2024, about work we had done customising the editor for that type of simplicity. And in particular things that we can do around colour palette selection. Ways that we can hide the styling controls for certain blocks through having them embedded in a pattern.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s interesting to see that in WordPress recently, if you are editing content that has been marked as having come from a pattern in a post, you can edit all of the text, you can edit all of the images and link targets, but you actually have to hit edit pattern in the sidebar in some cases, depending on how the post is set up, to get into the details within the post that allow all of those other controls to be visible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That divide took a tiny bit of adjustment for people on our client teams, but the separation has helped them stay focused on the content, and worry less about the overwhelming, combinatorial set of styling possibilities that their blocks have.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:29] <strong>Nathan Wrigley:</strong> Do you think that the necessary tools are already built into WordPress to do the kind of work that you are doing? Or is there some missing piece that would make it easier for somebody who doesn&#8217;t have the deep pockets that presumably Human Made would require, to do that kind of work. Is the default tooling usually okay to migrate things or have you had to build loads of bespoke tooling?</p>\n\n\n\n<p class=\"wp-block-paragraph\">So in terms of if I was to approach a WordPress website and try to migrate from Sitecore over to WordPress, is this something that you absolutely need a team to do, or would you be able to get some simulation of this with Core WordPress?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:04] <strong>K. Adam White:</strong> If you had access to the exports of data from a Sitecore website, and you had a core vanilla WordPress install. And you had a LLM tool of some sort, I think that you could do a lot to get close to what you want. The LLM piece, I think enables this to be done by more people without having to be completely familiar with all of the internal nuances of WordPress. You need to direct it to the architectural pattern that you want, but we have found that it speaks Gutenberg pretty well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:32] <strong>Nathan Wrigley:</strong> What was the name of the tool that you said you&#8217;d custom and built?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:34] <strong>K. Adam White:</strong> We had built a plugin called rehydrator.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:36] <strong>Nathan Wrigley:</strong> Okay, rehydrator, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:37] <strong>K. Adam White:</strong> rehydrator is the tool that we use to take a pattern in the theme and then use that pattern as the template when we&#8217;re bringing content over to make sure that we keep all of the styling theme side, and that our migration script doesn&#8217;t duplicate the markup specifically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:51] <strong>Nathan Wrigley:</strong> What&#8217;s Human Made&#8217;s approach to the WordPress project in that regard? You said it was a plugin. Does that mean it&#8217;s a wordpress.org repository plugin, or is it one that you have on your own, I don&#8217;t know, GitHub repository or whatever it may be.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:01] <strong>K. Adam White:</strong> We have some things in the .org repository. In this case, that particular plugin is only on GitHub. A number of ones that we build are only on GitHub, because we&#8217;re building them for a very transient in time period of a site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You don&#8217;t need a migration tool to be part of your site long term, it&#8217;s not something you&#8217;re going to be leaving active, and updating month over month when there is a site running. It&#8217;s something that you bring in for the purpose of populating the data. And then you can remove that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And in that regard, for this particular one, at the moment it&#8217;s partly because it&#8217;s quite young, and it&#8217;s also because we don&#8217;t see it as being general purpose. So that plugin specifically is on GitHub and publicly available through Composer, but not on the plugin directory.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In other situations, we&#8217;ve gone the opposite direction, and anything that we see as being a ongoing value to a site as it&#8217;s running, we do try to move those over as we can.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:52] <strong>Nathan Wrigley:</strong> Given that you are on the sort of engineering side of Human Made, I don&#8217;t know if this question will land, but we seem to be in this interesting period where there&#8217;s a lot of chatter, AI kind of fits into the equation a little bit, but there&#8217;s a lot of chatter about the, market share of WordPress and whether or not WordPress as a tool will continue with the same numbers and clout and market share and all of those kind of things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do you notice at the enterprise level that there&#8217;s been any kind of change in a southerly direction? Maybe there&#8217;s been a direct change in a northerly direction. What I&#8217;m trying to say is, for the enterprise, does WordPress still maintain that kind of pride place, top of the tree, or are you struggling to find new clients?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:28] <strong>K. Adam White:</strong> We&#8217;re not struggling to find new clients. We&#8217;re lucky that we&#8217;re doing quite well on marketing, and we also have had a very powerful year in terms of building relationships with new enterprises, and finding ways to take the technology that we believe in and solve their problems with it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I would argue that WordPress has never been the top of the enterprise space. And this actually goes back to your question about what is there that might be missing inside WordPress. The biggest thing that I think someone gets from a more, I&#8217;m going to use the term loosely, traditional enterprise CMS, is control.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And WordPress has a security model where the ability to edit and publish a piece of content is usually at the post level. There&#8217;s ways to add specific permission checks for metadata. There&#8217;s ways that you can restrict what&#8217;s accessible and editable with custom interfaces and custom API endpoints. But we tend to have things fall down to the capability checks for user can edit post 1, 2, 3. Yes. No.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that means that if you have a user profile where your organisation depends on someone being able to come in and touch only the headlines and the SEO metadata, we don&#8217;t really have a model for that right now in WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Whereas something like Sitecore, each individual, almost at the level of every string on the site, whether it&#8217;s a set of paragraphs or the label of a button, ends up as a individual node in the content tree. And those can be granted or denied to certain users on a much more granular level. So that to me is a bridge that I still am excited to see what we can do within WordPress to maybe build better interfaces, or better primitives in the editor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Block locking helps a little bit, but it is an API that&#8217;s quite difficult for some teams to wrap their heads around. And it also doesn&#8217;t really change the fact that if you can edit the post, and you were able to get the code editor up, then if you&#8217;re able to save it, you&#8217;re able to save it and doesn&#8217;t really go block by block. You&#8217;d have to write custom validation or permissions logic in order to be able to reject and update based on the user if they&#8217;re editing a block that is next to the one that they were supposed to.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:32] <strong>Nathan Wrigley:</strong> So do you have to present to the clients? It&#8217;ll be fine. This is what WordPress has. Don&#8217;t worry too much about it. If you&#8217;ve got this permission, yep, sure. You might be able to overlap and think people could delete things or modify things that perhaps they wouldn&#8217;t have to. That&#8217;s an educational piece on your side. Go and teach everybody not to mess around with things that they shouldn&#8217;t be messing around with.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But you would wish that in WordPress you could assign, say, as you described, this H1, this person can amend it, and this person can access the colour palette for the background image over here, but they can&#8217;t access the text. That kind of really granular permission. Whereas block locking just, it seems a bit more of a blunt instrument if you know what I mean. It&#8217;s binary. It&#8217;s locked or it&#8217;s not. You&#8217;d like to unlock the capabilities within each block so that certain users can do certain things within the same block.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:15] <strong>K. Adam White:</strong> Within blocks, we tend to rely on security through obscurity. We can hide or obfuscate controls behind block locking with content only. We can hide them behind patterns. But if someone&#8217;s coming to WordPress, we do make sure that they understand upfront what the nuance of control will be. And we will work with them usually to make things more editable.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Again, I will mention that most of the projects that we get that come from one of these more control-oriented CMSs into WordPress, what they&#8217;re seeking is actually more flexibility, not less. So they&#8217;re making a decision that they are willing to exchange the stringent control that they get in their existing tool for a process-based change. Maybe they add a review step, or add some sort of workflow plugin, so that we can validate that things look good and have someone sign off on it before it gets published. They would prefer to go that route than to sacrifice the ability for the editors to have the full control, and full pallet of options available to them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:13] <strong>Nathan Wrigley:</strong> Right, so that&#8217;s a much more loose approach. Everybody can maybe do more than they ought to do. If we have some editorial guideline where that can&#8217;t finally hit the public domain because the publish button is unavailable to you, that&#8217;s, okay. We&#8217;ll accept that kinda halfway house, if you like. That&#8217;s interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:30] <strong>K. Adam White:</strong> Each client&#8217;s needs are going to be slightly different. We do layer in publication checklists. We have tools to be able to say, this has to be tagged with the primary category before it goes live. We have tools to say, this still has lorum ipsum in it. You can add those in and build workflows, but I tend to like to help clients build processes to support those, rather than trying to take a draconian approach and lock everything down. Because then your work is going to be constantly chasing fine-grained permissions controls when you could be working to use that time making sure that all of the editors know what they can do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:04] <strong>Nathan Wrigley:</strong> I just want to drill into this a bit more. I know this isn&#8217;t where we were supposed to go, but I find it really interesting. Would you like those things to ship in Core? obviously they suit you down to the ground, all of those granular permissions, but do you think that belongs in Core?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:17] <strong>K. Adam White:</strong> I think that we need more workflow in Core.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:20] <strong>Nathan Wrigley:</strong> Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:20] <strong>K. Adam White:</strong> I know that there&#8217;s a number of different agencies and hosts which each have developed our own workflows solutions. I&#8217;ve worked across a number of them on projects that I&#8217;ve helped to support.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the notion that if you have something published and you make an edit out of the box, WordPress will automatically put live any further changes that you make to a published post when you hit save. That is probably the single thing that we most frequently have to build some type of plugin into a site to handle.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because we need to be able to give people an editorial review step. So that is something that I think we have a number of good tools, but I would love to see a more opinionated default in Core that we can use as a foundation for more complicated post editorial workflow. I think that&#8217;s the thing that we most frequently run into. That, and also I guess internationalisation are probably the two things that hopefully will come to the surface of the WordPress roadmap over time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:13] <strong>Nathan Wrigley:</strong> Yeah, I&#8217;d really not thought about that. Given Human Made&#8217;s sort of credentials and what have you. Do you have a lot of clout? Do you just punch above your weight in conversations about what makes it into Core? Do you get involved in those discussions? I&#8217;ve literally no idea how that would happen. Do you communicate to people when a release is coming around. Do you have a voice? Do you make yourself available? What is Human Made&#8217;s position in terms of getting things pushed into Core?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:37] <strong>K. Adam White:</strong> We participate in the project. I personally have been less involved in Core over the past several years than I would have hoped. I&#8217;ve been very much enjoying the detailed, quite close to the ground work that I&#8217;m doing on our agency projects. But unfortunately, I have taken a bit of a step back on the open source project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Some of my colleagues are in a slightly different boat. My colleague, John Blackbourn, our Director of Security for our own hosting product is also the head of the Security Team for WordPress? And has been helping us get the core patches out for the recent set of security releases.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We obviously will advocate in calls for feedback within the Gutenberg project when we feel that there&#8217;s a particular direction that we see from our projects. We are able to provide feedback on the UI, and the capabilities of new blocks that are being proposed. But that&#8217;s all done through the normal Gutenberg GitHub issue, and WordPress</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:28] <strong>Nathan Wrigley:</strong> So I think we should probably knock it on the head there. We&#8217;ve reached our allocated time. I&#8217;ll just point out that these days, it used to be the case that if I was at a WordCamp, you&#8217;d really have to wait about six months before the video for the presentation was available. I&#8217;m pretty sure it&#8217;ll be done already, in all honesty. 24 hours seems to be the time there. So if you were to go to WP Tavern, I will make sure that the link to the video, of K. Adam is there. If not, you can probably go to Google and search Migrating to Blocks, and in parenthesis, with Artisanal Care at Industrial Scale, and you&#8217;ll be able to see what it is that K. Adam was talking about.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But really, thank you so much for chatting to me today about all of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:06] <strong>K. Adam White:</strong> Thank you very much. And I can confirm that the video is already live on YouTube.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://www.linkedin.com/in/kadamwhite/\">K. Adam White</a>, or K. Adam for short.</p>\n\n\n\n<p class=\"wp-block-paragraph\">K. Adam is the principal engineer at Human Made, an enterprise WordPress consultancy. He’s been involved with WordPress almost 20 years, attended his first WordCamp in Boston back in 2011, and has contributed to WordPress Core and the broader open source ecosystem. Human Made is known for delivering complex projects, think high stakes, no room for mistakes, from global brands moving to WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This time around, K. Adam delivered a presentation at WordCamp US focused on a crucial topic for anyone modernising their site, migrating to blocks. Human Made has been all-in on the block editor since the Gutenberg plugin days, and the team now specialises in large-scale migrations from other content management systems like Sitecore, as well as from other WordPress page builders.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Our conversation focused on the technical and editorial challenges of moving tens or hundreds of thousands of posts into the world of blocks and patterns. We talked about the need to combine &#8220;artisanal care&#8221;, attention to detail in design, layout, and brand, with &#8220;industrial scale&#8221;, the ability to automate, audit, and validate mass migrations without losing visual fidelity.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also discussed the use of patterns as a foundation for development, integrating custom and Core blocks, and leveraging new tools (including AI-powered agents and open source plugins like Human Made’s own rehydrator) to streamline migration workflows. We also touched upon how clients are onboarded, the process of auditing legacy content, strategies for training editorial teams on the block editor, and there’s a frank reflection on gaps in WordPress, like granular content permissions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re contemplating a move to the block editor, wrestling with a massive content migration, or curious about what happens when enterprise complexity meets the flexibility of WordPress, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://humanmade.com\">Human Made</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://us.wordcamp.org/2026/session/migrating-to-blocks-with-artisanal-care-at-industrial-scale/\">Migrating to Blocks (With Artisanal Care, at Industrial Scale)</a> &#8211; K. Adam&#8217;s presentation at WordCamp US 2026</p>\n\n\n\n<p class=\"wp-block-paragraph\">Human Made&#8217;s <a href=\"https://github.com/humanmade/rehydrator\">rehydrator plugin on GitHub</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 23 Sep 2026 12:53:53 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:10;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"WordPress.org blog: WordPress 7.1.2 Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21731\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://wordpress.org/news/2026/09/wordpress-7-1-2-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3425:\"<p class=\"wp-block-paragraph\">This security release features a fix for a critical severity security vulnerability.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Because this is a security release, it is recommended that you update your sites immediately.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/download/\">download WordPress 7.1.2 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security update included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank <a href=\"https://ressl.ch/\">Robert Ressl</a> for responsibly disclosing that an unauthenticated attacker can, under certain conditions, make page template resolution include a chosen readable local PHP file outside the active theme directories. If relevant pre-conditions for both the server environment and the active theme are met, this can lead to remote code execution (RCE).</p>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>. WordPress 7.1.2 would not have been possible without the contributions of the following people:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@wildworks\">Aki Hamano</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@ehti\">Ehtisham Siddiqui</a>, <a href=\"https://w.org/@fiocavallari\">fiocavallari</a>, <a href=\"https://w.org/@audrasjb\">Jb Audras</a>, <a href=\"https://w.org/@jeffpaul\">Jeffrey Paul</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@joemcgill\">Joe McGill</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@sirlouen\">Manuel Camargo</a>, <a href=\"https://w.org/@marcs0h\">marcs0h</a>, <a href=\"https://w.org/@martinkrcho\">martin.krcho</a>, <a href=\"https://w.org/@mukesh27\">Mukesh Panchal</a>, <a href=\"https://w.org/@oglekler\">Olga Gleckler</a>, <a href=\"https://w.org/@swissspidy\">Pascal Birchler</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@rajinsharwar\">Rajin Sharwar</a>, <a href=\"https://w.org/@ressl\">Ressl</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://w.org/@shailu25\">Shail Mehta</a>, <a href=\"https://w.org/@pypwalters\">Stephanie Walters</a>, and <a href=\"https://w.org/@vortfu\">vortfu</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">CVE and GHSA references</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Further details can be found in the advisory: <a href=\"https://github.com/WordPress/wordpress-develop/security/advisories/GHSA-7hp8-65ch-5whp\">CVE-2026-87902 / GHSA-7hp8-65ch-5whp</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fix was backported to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 22 Sep 2026 14:01:20 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"John Blackbourn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:11;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:107:\"Open Channels FM: Balancing Tradition and Innovation in Genealogy During the Era of Artificial Intelligence\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562212\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:114:\"https://openchannels.fm/balancing-tradition-and-innovation-in-genealogy-during-the-era-of-artificial-intelligence/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:111:\"I makes genealogy faster and more accurate while Charleen Mullenweg explains the ongoing need for human review.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 22 Sep 2026 12:02:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:12;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:98:\"Open Channels FM: Invisible Unicode Attacks, CrowdSec Source Leak, and the AI Coding Boom Explored\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562271\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:103:\"https://openchannels.fm/invisible-unicode-attacks-crowdsec-source-leak-and-the-ai-coding-boom-explored/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:134:\"Invisible characters challenge spam filters, CrowdSec deals with a code leak, and AI is shifting what matters in software development.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 21 Sep 2026 15:30:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:13;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"bbPress: bbPress 2.6.18 is out!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://bbpress.org/?p=249876\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://bbpress.org/blog/2026/09/bbpress-2-6-18-is-out/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1178:\"<p class=\"wp-block-paragraph\">bbPress 2.6.18 is a maintenance release focused on forum imports and first-login password upgrades.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Imported users can now upgrade their passwords on first login for more legacy forum formats, including cases where the original forum database is no longer available. This release also corrects PHPWind topic statuses, reply counts, and forum dates during import, and restores Super Moderator edit links on front-end bbPress user screens.</p>\n\n\n\n<p class=\"wp-block-paragraph\">bbPress 2.6.18 requires PHP 7.2 or newer and WordPress 6.0 or newer. Sites running an older PHP version should update PHP before upgrading bbPress. <a href=\"https://codex.bbpress.org/releases/bbpress-2-6-18/\">Read the 2.6.18 upgrade notes</a> for importer compatibility details.</p>\n\n\n\n<p class=\"wp-block-paragraph\">These changes are also in the 2.7 development branch. The Plugin Directory’s development trunk remains at 2.7.0-alpha-3.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://downloads.wordpress.org/plugin/bbpress.2.6.18.zip\">Download bbPress 2.6.18</a> from WordPress.org, or update from your WordPress dashboard.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 21 Sep 2026 14:53:41 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"John James Jacoby\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:14;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"WordPress.org blog: WordPress Takes Its Turn Leading the Open Website Alliance\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21709\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:49:\"https://wordpress.org/news/2026/09/owa-president/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2391:\"<p class=\"wp-block-paragraph\">I’m happy to announce that I am now serving as president of the <a href=\"https://openwebsitealliance.org/\">Open Website Alliance</a> (OWA), representing the WordPress Foundation. The Alliance brings together the community organizations behind <a href=\"https://www.drupal.org/\">Drupal</a>, <a href=\"https://www.joomla.org/\">Joomla!</a>, <a href=\"https://typo3.org/\">TYPO3</a>, and WordPress to advocate for open source and share practices that benefit their projects. I represent the WordPress Foundation in this role, which rotates among the Alliance’s members.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-21712\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/09/image-3.png?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress <a href=\"https://x.com/WordPress/status/1755516866485707064\">announced its participation in the Alliance in 2024</a>, building on our work with Drupal, Joomla!, and TYPO3 to <a href=\"https://wordpress.org/news/2023/08/concerns-over-the-european-unions-cyber-resilience-act-cra/\">respond to the European Union’s Cyber Resilience Act</a>. While many open source projects focus on underlying digital infrastructure, our content management systems power the websites where businesses reach customers and sell products and services. We asked policymakers to account for that economic role when setting security requirements, while respecting how communities of developers, translators, educators, and other contributors build and maintain the software. We share a belief that everyone should have the freedom to use, change, and share the tools they rely on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This commitment to openness builds on efforts such WordPress’s recent signing of the <a href=\"https://wordpress.org/news/2026/08/open-weight/\">Open Weights and American AI Leadership letter</a>. Our mission to democratize publishing means giving anyone a voice and welcoming everyone to contribute. Working with other communities puts those values into practice beyond WordPress, supporting the freedoms that make participation possible. I invite you to read the <a href=\"https://openwebsitealliance.org/charter.html\">Open Website Alliance charter</a> to learn more about the commitments its members share and how the Alliance works.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 21 Sep 2026 14:28:41 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Mary Hubbard\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:15;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:77:\"OpenStation Blog: Drag, Drop, Preview: How a Post Gets Written in OpenStation\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://openstation.blog/?p=1220\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:93:\"https://openstation.blog/2026/09/21/drag-drop-preview-an-ordinary-day-writing-in-openstation/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2340:\"<p class=\"wp-block-paragraph\">I started writing a post (this post!).</p>\n\n\n\n<p class=\"wp-block-paragraph\">Then, as usually happens, I needed a picture, so I dragged one straight from my desktop into OpenStation. No downloading, no extra tabs needed, no extra spaces in the editor, no more &#8220;in which tab was the image!?&#8221;&#8230; I just dragged it from my desktop&#8230;</p>\n\n\n\n<figure class=\"wp-block-image alignfull\"><img alt=\"Happy\" src=\"https://i0.wp.com/live.staticflickr.com/8449/8006853151_5881bfe507_b.jpg?ssl=1\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Done!</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then I thought the post was already descriptive enough to tell how much we enjoy creating content in OpenStation&#8230; But I missed the preview. I wanted to see what the post would look like and edit it in real time. And it happened, I just had to click on the eye icon in the title bar of this editor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This is probably my favourite kind of productivity, the boring stuff becoming pleasantly simple&#8230;</p>\n\n\n\n<p class=\"wp-block-paragraph\">And yes, this whole post was written while recording the video <img alt=\"🙂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f642.png\" style=\"height: 1em;\" /></p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<p class=\"wp-block-paragraph\">But I thought that a quick sanity review from one of my bots would make the post nicer for SEO. So I just saved the draft, and gave it to my agent <img alt=\"😉\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f609.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">And the best part, is that <strong>EVERYTHING</strong> that my Agent did, is traceable.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"Dashboard view for SEO Medic user profile in OpenStation, showing user information, total content, comments, updates, and recent activity.\" class=\"wp-image-1246\" height=\"572\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/image-12.png?resize=1024%2C572&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"has-text-align-center wp-block-paragraph\"><strong>Switch to OpenStation</strong></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 21 Sep 2026 13:39:51 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Daniel López\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:16;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"Open Channels FM: AI for the Rest of Us, Beyond the Bubble\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562231\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"https://openchannels.fm/ai-for-the-rest-of-us-beyond-the-bubble/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"Bob Dunn talks about breaking out of AI echo chambers to gain new insights\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 21 Sep 2026 09:35:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:17;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"OpenStation Blog: A better way to use WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://openstation.blog/?p=1160\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"https://openstation.blog/2026/09/18/a-better-way-to-use-wordpress/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:5884:\"<p class=\"wp-block-paragraph\">I have been using WordPress for a long time, and I still love it. But <code>wp-admin</code> has basically worked in the same way for years.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>OpenStation</strong> is our attempt to change that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s a simple idea: instead of moving from one admin page to another, you have a desktop where you can open different parts of WordPress at the same time.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"A screenshot of the OpenStation interface displaying a welcome message and a list of recent posts on the left, with a detailed view of the \'A better way to use WordPress\' post on the right.\" class=\"wp-image-1162\" height=\"493\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/image-7.png?resize=1024%2C493&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Your WordPress. Your workspace.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can open your posts, pages, media, plugins, WooCommerce or any OpenStation app in different windows.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can move them around, minimize them or put two things next to each other.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It may sound like a small difference, but once you start using WordPress this way, it changes a lot.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Real-time previews</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can also see your changes while you are working on them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">No need to constantly jump between wp-admin and the frontend just to check how something looks.</p>\n\n\n\n<figure class=\"wp-block-image\"><img alt=\"Screenshot of an OpenStation interface showcasing a blog post titled \'A better way to use WordPress\' with a dark theme and multiple sections discussing features and mobile compatibility.\" class=\"wp-image-1164\" height=\"497\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/image-8.png?resize=1024%2C497&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Apps inside WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This is one of my favorite parts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We are building apps like AllTerrain Forms, Photo Editor (And more!) specifically for OpenStation.</p>\n\n\n\n<p class=\"wp-block-paragraph\">They are still WordPress plugins, but they feel much more like normal desktop apps.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"A black Nike Air Force 1 sneaker displayed on a table, featuring a blue swoosh and \'OpenStation\' branding.\" class=\"wp-image-1168\" height=\"673\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/image-9.png?resize=1024%2C673&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">WordPress on your phone</h2>\n\n\n\n<p class=\"wp-block-paragraph\">We also wanted OpenStation to work properly on mobile.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can install it as a PWA and use WordPress from your phone almost like any other app.</p>\n\n\n\n<figure class=\"wp-block-image aligncenter size-full\"><img alt=\"A digital interface displaying a grid of application icons with sections for apps and system tools, including options for dashboard, posts, media, and settings.\" class=\"wp-image-1170\" height=\"850\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/image-10.png?resize=493%2C850&#038;ssl=1\" width=\"493\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Performance Is Fast. Really fast.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">OpenStation is not only about changing how WordPress looks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We have put a lot of work into making it fast. In many cases, opening and moving between WordPress screens is faster than using them directly from wp-admin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We are also working on caching and preloading parts of WordPress before you need them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The goal is very simple: you click something and it opens FAST.</p>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-9-16 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n\n\n\n<h2 class=\"wp-block-heading\">And it is still WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This is important.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We are not trying to replace WordPress or build another platform on top of it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Your plugins are still your plugins. WooCommerce is still WooCommerce. Your content stays in WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">OpenStation just gives you a different way to use all of it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, of course, it is open source.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you</h2>\n\n\n\n<p class=\"wp-block-paragraph\">And finally, a big thank you to everyone in the WordPress community who has tried OpenStation, shared feedback, reported bugs or simply told others about it.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"Grid of contributors to OpenStation showcasing their profile pictures and the number of merged pull requests (PRs) each has contributed.\" class=\"wp-image-1190\" height=\"578\" src=\"https://i0.wp.com/openstation.blog/wp-content/uploads/2026/09/image-11.png?resize=1024%2C578&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">And especially to all the contributors who are helping us build it. OpenStation would not be what it is today without you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There is still a lot we want to do, and seeing people contributing, experimenting and building things with OpenStation is probably the best part of the whole project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you <img alt=\"❤\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/2764.png\" style=\"height: 1em;\" /></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 18 Sep 2026 15:21:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"Daniel López\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:18;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:39:\"Open Channels FM: OCN Week in Review #4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562022\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:45:\"https://openchannels.fm/ocn-week-in-review-4/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:428:\"This week Robert Jacobi shared about  the evolving landscape of open source and tech. Highlights include AI’s growing role in security, WordPress and Apache fortifying their processes, LibreOffice redefining productivity with privacy, LoopConf rethinking event funding, and Switzerland’s bold move toward digital sovereignty. Explore how accountability, control, and sustainability are shaping the future of open technology.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 18 Sep 2026 13:45:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:19;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"Open Channels FM: Drawing the Line Between Openness and Noise in the Digital World\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2562008\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://openchannels.fm/drawing-the-line-between-openness-and-noise-in-digital-world/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:100:\"Is sharing everything always good? Bob Dunn reflects on transparency and the noise in online spaces.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 18 Sep 2026 12:30:44 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:20;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"WordPress.org blog: WordPress 7.1.1 Maintenance and Security Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21717\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"https://wordpress.org/news/2026/09/wordpress-7-1-1-maintenance-and-security-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:12736:\"<p class=\"wp-block-paragraph\">This security and maintenance release features <a href=\"https://core.trac.wordpress.org/query?milestone=7.1.1&amp;status=closed&amp;group=status&amp;order=priority\">17 bug fixes on Core</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82383\">19 bug fixes for the Block Editor</a>, and 11 security fixes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Because this is a security release, it is recommended that you update your sites immediately.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/wordpress-7.1.1.zip\">download WordPress 7.1.1 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1.1 is a short-cycle release. The next major release will be <a href=\"https://make.wordpress.org/core/7-2/\">version 7.2</a> and is currently planned for December.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more information, please visit the <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-1-1/\">WordPress 7.1.1 HelpHub site</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank the following people for responsibly reporting vulnerabilities, and allowing them to be fixed in this release:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Stored cross-site scripting in <code>wpautop()</code> allows an unauthenticated visitor to inject script (subject to comment approval), reported by <a href=\"https://www.linkedin.com/in/rafiemuhammad/\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>HTML API: <code>set_modifiable_text()</code> allows breaking out of a comment via abrupt-closing sequences, reported by <a href=\"https://happyprime.co/\">Jeremy Felt</a> of the WordPress Security Team.</li>\n\n\n\n<li>Stored XSS in some themes that support custom headers, reported by <a href=\"https://happyprime.co/\">Jeremy Felt</a> of the WordPress Security Team.</li>\n\n\n\n<li>Specially crafted URLs can automatically install and preview an inactive theme from WordPress.org, reported by Paulos Yibelo and <a href=\"https://pwn.ai/\">pwn.ai</a>.</li>\n\n\n\n<li>Site Administrator can network-activate an installed Network-only plugin, reported by <a href=\"https://profiles.wordpress.org/buffer1024/\">Jesse McNeil</a>.</li>\n\n\n\n<li>Authenticated Path Traversal in WP REST Templates Controller, reported by Anthropic.</li>\n\n\n\n<li>XML-RPC can be used to publish <code>customize_changeset</code> posts that bypass checks for <code>edit_css</code>, reported by Ben Bidner of the WordPress Security Team.</li>\n\n\n\n<li>Contributor+ Arbitrary Post Overwrite, reported by Anthropic.</li>\n\n\n\n<li>Missing <code>read_post</code> check in <code>attachment_submitbox_metadata()</code> leaks a private parent-post title, reported by <a href=\"https://hdwsec.fr/\">HDWSec</a>.</li>\n\n\n\n<li>Missing Authorization leads to Draft/Pending Post Slug Disclosure by Contributor+, reported by Jakub Herman.</li>\n\n\n\n<li>Comments, including notes, can be reparented by any authenticated user, reported by Justin Hart, Viridis Security.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a>, <a href=\"https://profiles.wordpress.org/adrianduffell/\">Adrian Duffell</a>, <a href=\"https://profiles.wordpress.org/andraganescu/\">Andrei Draganescu</a>, and <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1.1 would not have been possible without the contributions of the following people. Their asynchronous coordination to deliver maintenance and security fixes into a stable release is a testament to the power and capability of the WordPress community.</p>\n\n\n\n<p class=\"is-style-wporg-props-long wp-block-paragraph\"><a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/abrahamfariaz/\">abrahamfariaz</a>, <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a>, <a href=\"https://profiles.wordpress.org/adrianmoldovanwp/\">Adi Moldovan</a>, <a href=\"https://profiles.wordpress.org/adrianduffell/\">Adrian Duffell</a>, <a href=\"https://profiles.wordpress.org/wildworks/\">Aki Hamano</a>, <a href=\"https://profiles.wordpress.org/xknown/\">Alex Concha</a>, <a href=\"https://profiles.wordpress.org/afercia/\">Andrea Fercia</a>, <a href=\"https://profiles.wordpress.org/andreasca/\">andreasca</a>, <a href=\"https://profiles.wordpress.org/andraganescu/\">Andrei Draganescu</a>, <a href=\"https://profiles.wordpress.org/aduth/\">Andrew Duthie</a>, <a href=\"https://profiles.wordpress.org/andrewserong/\">Andrew Serong</a>, <a href=\"https://profiles.wordpress.org/oandregal/\">André Maneiro</a>, <a href=\"https://profiles.wordpress.org/annezazu/\">annezazu</a>, <a href=\"https://profiles.wordpress.org/antwonw/\">Anthony White</a>, <a href=\"https://profiles.wordpress.org/arkaprabhachowdhury/\">Arkaprabha Chowdhury</a>, <a href=\"https://profiles.wordpress.org/fushar/\">Ashar Fuadi</a>, <a href=\"https://profiles.wordpress.org/azragh/\">Azragh</a>, <a href=\"https://profiles.wordpress.org/barry/\">Barry</a>, <a href=\"https://profiles.wordpress.org/buffer1024/\">buffer1024</a>, <a href=\"https://profiles.wordpress.org/jack960330/\">Chunhui Ouyang</a>, <a href=\"https://profiles.wordpress.org/courane01/\">Courtney Robertson</a>, <a href=\"https://profiles.wordpress.org/dugi-digitaly/\">Dagan</a>, <a href=\"https://profiles.wordpress.org/talldanwp/\">Daniel Richards</a>, <a href=\"https://profiles.wordpress.org/villanovachile/\">Daniel Rodriguez</a>, <a href=\"https://profiles.wordpress.org/darshitrajyaguru97/\">Darshit Rajyaguru</a>, <a href=\"https://profiles.wordpress.org/davidbinda/\">David Biňovec</a>, <a href=\"https://profiles.wordpress.org/iamchitti/\">Deepak Kumar</a>, <a href=\"https://profiles.wordpress.org/dmsnell/\">Dennis Snell</a>, <a href=\"https://profiles.wordpress.org/saiful09/\">DevSaiful</a>, <a href=\"https://profiles.wordpress.org/dhruvang21/\">Dhruvang21</a>, <a href=\"https://profiles.wordpress.org/ocean90/\">Dominik Schilling</a>, <a href=\"https://profiles.wordpress.org/ehtis/\">Ehtisham Siddiqui</a>, <a href=\"https://profiles.wordpress.org/ellatrix/\">Ella Van Durpe</a>, <a href=\"https://profiles.wordpress.org/r1k0/\">Erick Wambua</a>, <a href=\"https://profiles.wordpress.org/fahimmurshed/\">FahimMurshed</a>, <a href=\"https://profiles.wordpress.org/fernandot/\">Fernando Tellado</a>, <a href=\"https://profiles.wordpress.org/fiocavallari/\">fiocavallari</a>, <a href=\"https://profiles.wordpress.org/mamaduka/\">George Mamadashvili</a>, <a href=\"https://profiles.wordpress.org/poseidonas/\">George Vasiliades</a>, <a href=\"https://profiles.wordpress.org/gregbenz/\">gregbenz</a>, <a href=\"https://profiles.wordpress.org/harishtewari/\">Harish Tewari</a>, <a href=\"https://profiles.wordpress.org/hbhalodia/\">Hit Bhalodia</a>, <a href=\"https://profiles.wordpress.org/isabel_brison/\">Isabel Brison</a>, <a href=\"https://profiles.wordpress.org/whyisjake/\">Jake Spurlock</a>, <a href=\"https://profiles.wordpress.org/jdab/\">Jamie Dąbrowiecki</a>, <a href=\"https://profiles.wordpress.org/audrasjb/\">Jb Audras</a>, <a href=\"https://profiles.wordpress.org/jeffpaul/\">Jeffrey Paul</a>, <a href=\"https://profiles.wordpress.org/jeremyfelt/\">Jeremy Felt</a>, <a href=\"https://profiles.wordpress.org/kimjiwoon/\">Jiwoon Kim</a>, <a href=\"https://profiles.wordpress.org/joedolson/\">Joe Dolson</a>, <a href=\"https://profiles.wordpress.org/joehoyle/\">Joe Hoyle</a>, <a href=\"https://profiles.wordpress.org/joemcgill/\">Joe McGill</a>, <a href=\"https://profiles.wordpress.org/joen/\">Joen Asmussen</a>, <a href=\"https://profiles.wordpress.org/timse201/\">Johannes Jülg</a>, <a href=\"https://profiles.wordpress.org/johnbillion/\">John Blackbourn</a>, <a href=\"https://profiles.wordpress.org/jonsurrell/\">Jon Surrell</a>, <a href=\"https://profiles.wordpress.org/desrosj/\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/jmccallweb/\">Josh</a>, <a href=\"https://profiles.wordpress.org/ekamran/\">Kamran Abdul Aziz</a>, <a href=\"https://profiles.wordpress.org/khokansardar/\">Khokan Sardar</a>, <a href=\"https://profiles.wordpress.org/kirasong/\">Kira Schroder</a>, <a href=\"https://profiles.wordpress.org/kleisauke/\">kleisauke</a>, <a href=\"https://profiles.wordpress.org/kush123/\">Kushagra Goyal</a>, <a href=\"https://profiles.wordpress.org/l1onofjudah/\">l1onofjudah</a>, <a href=\"https://profiles.wordpress.org/lancewillett/\">Lance Willett</a>, <a href=\"https://profiles.wordpress.org/luksusspokoju/\">luksusspokoju</a>, <a href=\"https://profiles.wordpress.org/manzoorwanijk/\">Manzoor Wani</a>, <a href=\"https://profiles.wordpress.org/mciampini/\">Marco Ciampini</a>, <a href=\"https://profiles.wordpress.org/marcs0h/\">marcs0h</a>, <a href=\"https://profiles.wordpress.org/tyxla/\">Marin Atanasov</a>, <a href=\"https://profiles.wordpress.org/mgyura/\">Michael</a>, <a href=\"https://profiles.wordpress.org/batmoo/\">Mohammad Jangda</a>, <a href=\"https://profiles.wordpress.org/mrkenobi/\">mrkenobi</a>, <a href=\"https://profiles.wordpress.org/mukesh27/\">Mukesh Panchal</a>, <a href=\"https://profiles.wordpress.org/nkpathan/\">Nawazkhan Pathan</a>, <a href=\"https://profiles.wordpress.org/ntsekouras/\">Nik Tsekouras</a>, <a href=\"https://profiles.wordpress.org/parthjoginyusoft/\">Parth Jogi</a>, <a href=\"https://profiles.wordpress.org/swissspidy/\">Pascal Birchler</a>, <a href=\"https://profiles.wordpress.org/pbiron/\">Paul Biron</a>, <a href=\"https://profiles.wordpress.org/paulkevan/\">Paul Kevan</a>, <a href=\"https://profiles.wordpress.org/peterwilsoncc/\">Peter Wilson</a>, <a href=\"https://profiles.wordpress.org/rafiem/\">Rafie Muhammad</a>, <a href=\"https://profiles.wordpress.org/ramonopoly/\">ramonopoly</a>, <a href=\"https://profiles.wordpress.org/wprashed/\">Rashed Hossain</a>, <a href=\"https://profiles.wordpress.org/ressl/\">Ressl</a>, <a href=\"https://profiles.wordpress.org/youknowriad/\">Riad Benguella</a>, <a href=\"https://profiles.wordpress.org/rfaile313/\">Rudy Faile</a>, <a href=\"https://profiles.wordpress.org/sainathpoojary/\">Sainath Poojary</a>, <a href=\"https://profiles.wordpress.org/sc0ttkclark/\">Scott Kingsley Clark</a>, <a href=\"https://profiles.wordpress.org/sergeybiryukov/\">Sergey Biryukov</a>, <a href=\"https://profiles.wordpress.org/shailu25/\">Shail Mehta</a>, <a href=\"https://profiles.wordpress.org/shameemreza/\">Shameem – a11n</a>, <a href=\"https://profiles.wordpress.org/siliconforks/\">siliconforks</a>, <a href=\"https://profiles.wordpress.org/slaffik/\">Slava Abakumov</a>, <a href=\"https://profiles.wordpress.org/sabernhardt/\">Stephen Bernhardt</a>, <a href=\"https://profiles.wordpress.org/sukhendu2002/\">Sukhendu Sekhar Guria</a>, <a href=\"https://profiles.wordpress.org/ugyensupport/\">Ugyen Dorji</a>, <a href=\"https://profiles.wordpress.org/utsavladani/\">Utsav Ladani</a>, <a href=\"https://profiles.wordpress.org/vortfu/\">vortfu</a>, <a href=\"https://profiles.wordpress.org/westonruter/\">Weston Ruter</a>, <a href=\"https://profiles.wordpress.org/w3bdsgn/\">w3bdsgn</a>, <a href=\"https://profiles.wordpress.org/wolf45/\">wolf45</a> plus representatives from Automattic, Bluehost, GoDaddy, Pantheon, and WP Engine.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fixes are being backported, where necessary, to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to contribute</h2>\n\n\n\n<p class=\"wp-block-paragraph\">To get involved in WordPress core development, head over to Trac, <a href=\"https://core.trac.wordpress.org/report/6\">pick a ticket</a>, and join the conversation in the <a href=\"https://wordpress.slack.com/archives/C02RQBWTW\">#core</a> channel. Need help? Check out the <a href=\"https://make.wordpress.org/core/handbook/\">Core Contributor Handbook</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Props to <a href=\"https://profiles.wordpress.org/ehtis/\">Ehtisham Siddiqui</a>, <a href=\"https://profiles.wordpress.org/lancewillett/\">Lance Willett</a>, <a href=\"https://profiles.wordpress.org/westonruter/\">Weston Ruter</a>, and <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a> for proofreading.</em></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 17 Sep 2026 19:53:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Aaron Jorbin\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:21;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"Open Channels FM: Open Source Economics, LibreOffice, and Swiss Digital Sovereignty\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561963\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"https://openchannels.fm/open-source-economics-libreoffice-and-swiss-digital-sovereignty/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:112:\"Shifting budgets and tech priorities drive change for open source events software and government infrastructure.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 17 Sep 2026 16:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:22;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"Matt: OmFest: A Celebration of Curiosity, Connection, and the Future\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=154845\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://ma.tt/2026/09/omfest-soon/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:7320:\"<figure class=\"wp-block-image alignwide size-large\"><img alt=\"\" class=\"wp-image-154877\" height=\"267\" src=\"https://i0.wp.com/ma.tt/files/2026/09/b97df-all-roads-lead-to-om-1-1024x452.jpg?resize=604%2C267&#038;quality=89&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">OmFest is coming together quite nicely! The <a href=\"https://omfest.co/\">new website is beautiful and highlights some of the experiences available throughout the day</a>. I think Om would be very impressed by the attendee list. We&#8217;re doing it at the <a href=\"https://www.swedishamericanhall.com/\">Swedish American Hall</a>, the same venue as <a href=\"https://sf.wordcamp.org/2006/\">the first WordCamp</a>, where Om, of course, <a href=\"https://sf.wordcamp.org/2006/schedule/\">spoke about Blogs and Journalism</a>. (The videos have been lost to digirot, unless anyone has some recordings? I&#8217;ve been looking everywhere.)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Below is cross-posted from <a href=\"https://omfest.co/\">OmFest.co</a>:</p>\n\n\n\n<p class=\"wp-block-paragraph\">September 29<sup>th</sup> is when Om would have turned 60. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://ma.tt/2026/06/om-forever/\">When I first started thinking about how to mark the day</a>, I knew I didn’t want a traditional memorial. Om loved bringing interesting people together, and he loved a festival that taught him something he didn’t already know. His curiosity crossed so many worlds and passions: technology, journalism, photography, investing, watches, pens, coffee, design, music, India, New York, San Francisco. </p>\n\n\n\n<p class=\"wp-block-paragraph\">So we’re bringing these worlds together. On September 29 in San Francisco, we’re throwing OmFest—twelve hours of ideas, objects, food, music, and conversation, organized and anchored around a statement Om once said:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"is-style-default has-quote-font-size wp-block-paragraph\">“If you pay enough attention to the present, you can see the future.”</p>\n</blockquote>\n\n\n\n<h2 class=\"wp-block-heading\">Present Future</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Instead of tributes or keynotes, we’ll host a series of short talks with one simple challenge: teach us something you’re seeing before everyone else sees it. No pitches, no career retrospectives. You don’t even have to talk about Om. What happens to photography when anyone can generate the perfect image with AI? Why do physical objects become more meaningful as our lives become more digital? Are glasses becoming computers? What does handwriting do to the way we think? Different subjects, same goal: everyone leaves knowing something they didn’t know when they arrived.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Festival of Om’s Curiosity </h2>\n\n\n\n<p class=\"wp-block-paragraph\">Between the talks, there will be plenty to stumble upon. Through Om’s Lens: a gallery of Om’s photography. TIME: an exhibit that uses his watch obsession to spark a discussion about craft and collecting. Field Notes: a communal writing table stocked with fine paper, fountain pens, and ink, where you can write something worth remembering—and either keep it or leave it behind to be bound in a book to commemorate the day. And Om’s Shelf: books he read, loved, and recommended. The collection will start full and slowly empty as his favorite reads pass into other hands.</p>\n\n\n\n<p class=\"wp-block-paragraph\">People from Om’s different worlds will drop in throughout the day to share knowledge and facilitate small, hands-on moments: a photography tutorial, a notebook-binding session, a lesson on the mechanics of a watch, an experience with a coffee you’ve never tried, a tea ceremony. And, woven into this experience, will be OM/60: sixty small discoveries about Om, hidden throughout. </p>\n\n\n\n<h2 class=\"wp-block-heading\">All Roads Lead to Om</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The most important part, however, isn’t any of these objects. At check-in, instead of a badge with your company and title, you’ll choose the worlds through which you knew Om: photography, journalism, technology, GigaOm, investing, WordPress, India, coffee, pens and ink, design, music, or simply friends and family.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Then we build a physical map of it. It starts nearly empty. You add yourself, mark how you knew Om and whom he introduced you to, and those people connect to others. By the end of the night, I hope we’ll be able to see what Om spent a lifetime making. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The question I keep asking myself: who will meet because of Om that Om never had the chance to introduce? If OmFest works, his network won’t just be documented that day. It’ll grow. </p>\n\n\n\n<h2 class=\"wp-block-heading\">From Ideas to Celebration</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The day flows and builds. Morning is coffee, breakfast, books, photography, and conversation. The middle is deliberately unstructured—wander, eat, write, talk. In the evening, friends share short stories as we raise a glass to Om on his 60th. Then the bars roll in, the lights go down, the music gets louder, and OmFest becomes DesiParty: his old-school New York nights, Asian Underground, bhangra, electronica. We start with ideas and end with dancing. That feels right.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Version 1.0</h2>\n\n\n\n<p class=\"wp-block-paragraph\">What we’re building shouldn’t end on September 29. What does registration look like if it’s designed to help strangers talk to each other? How do you design a conference around curiosity instead of status? How do you make something that works for a two-hour visit or a twelve-hour one? How does a room encourage connection without forcing networking? </p>\n\n\n\n<p class=\"wp-block-paragraph\">We’re treating OmFest as an experiment. We’ll document what works—formats, designs, code, templates, check-in, programming—and open source as much of it as we can. Other events can take the best ideas and make them better.  </p>\n\n\n\n<p class=\"wp-block-paragraph\">September 29 isn’t the end of OmFest. It’s version 1.0. </p>\n\n\n\n<h2 class=\"wp-block-heading\">Come Build with Us</h2>\n\n\n\n<p class=\"wp-block-paragraph\">People from across Om’s life are building OmFest together. Some are contributing photographs. Someone is making a textile; another is bringing tea and guiding ceremonies. Others are helping with watches, eyewear, books, music, writing, and stories. We haven&#8217;t discovered whole parts of Om’s world yet. That’s the point.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If Om introduced you to something, or someone, we’d love to know. <a href=\"https://docs.google.com/forms/d/e/1FAIpQLScyY9c5MowPFW6BmIitqaaF3T-ykM_d8eD2pq2XqwSt7N50zg/viewform\">If there’s something you think people should experience, see, hear, taste, read, or learn that day, tell us</a>. </p>\n\n\n\n<p class=\"wp-block-paragraph\">And if you just want to come, come. You don’t need to have known Om. You only need to be curious.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://luma.com/om-fest\">RSVP here</a></div>\n</div>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 17 Sep 2026 01:04:27 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:23;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Matt: Mirene\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=154872\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://ma.tt/2026/09/mirene-2/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:245:\"<p class=\"wp-block-paragraph\">It&#8217;s official in SF Standard: <a href=\"https://sfstandard.com/2026/09/16/matt-mullenweg-buys-stewart-brand-houseboat-sausalito/\">Stewart Brand sells his seaworthy Sausalito houseboat to tech CEO</a>. Ahoy!</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 17 Sep 2026 00:45:36 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:24;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:131:\"Open Channels FM: Scaling Security WordPress Reinvents Protection and Apache Bolsters Infrastructure While Zephyr Expands Ecosystem\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561934\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:138:\"https://openchannels.fm/scaling-security-wordpress-reinvents-protection-and-apache-bolsters-infrastructure-while-zephyr-expands-ecosystem/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:128:\"WordPress, Apache, and Zephyr adapt to AI-driven security and infrastructure demands shaping the future of open source at scale.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 16 Sep 2026 16:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:25;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"Open Channels FM: Navigating Founder-Led Sales in Today’s Market\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2560839\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"https://openchannels.fm/navigating-founder-led-sales-in-todays-market/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:210:\"Founder-led sales focus on authentic outreach and relationship building, prioritizing genuine engagement in communities over cold pitches, fostering trust, and recognizing that not every prospect is a good fit.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 16 Sep 2026 12:53:50 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:26;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"bbPress: bbPress 2.6.17 is out!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://bbpress.org/?p=249814\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://bbpress.org/blog/2026/09/bbpress-2-6-17-is-out/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2627:\"<p class=\"wp-block-paragraph\">bbPress 2.6.17 is a security and maintenance release with broad improvements to permissions, private content, subscriptions, moderation workflows, and forum counts. Everyone running bbPress should update as soon as possible. <img alt=\"🔒\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f512.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">(You may notice 2.6.17 release follows 2.6.15. Well, I found a SQL bug right after 2.6.16 was tagged and I didn&#8217;t want to wait to get that fix out, sooooo&#8230; here we are!)</p>\n\n\n\n<p class=\"wp-block-paragraph\">This release strengthens inherited private and hidden forum visibility, BuddyPress Group Forum boundaries, subscriber access checks, profile editing, REST API and XML-RPC requests, search results, canonical redirects, topic tags, reply moves, topic splits, and output escaping.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It also includes a substantial overhaul of count maintenance and repair tools, improving topic, reply, forum, subforum, engagement, voice, and user contribution counts across moderation, moves, merges, splits, deletion, restoration, reassignment, and simultaneous requests. Block Themes now receive first-class support while continuing to use bbPress&#8217;s PHP templates, and the Plugin Directory gains a populated WordPress Playground preview.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Developers should review the <a href=\"https://codex.bbpress.org/releases/bbpress-2-6-17/\">2.6.17 upgrade notes</a>, especially if an integration hooks bbPress creation or moderation actions for counts, filters custom statuses or count values, customizes subforum queries, or overrides <code>form-user-roles.php</code>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">All of these changes have also been merged into the 2.7 development branch, which is now at 2.7.0-alpha-3.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you to obenland, hoangkien1020, rafiem, faran66, im_rootkid, winty, winstoncrooker, vvh1te3zz, mickey_cyberkid, phanphanhailong, hieunx91, jassbugbounty, nextdoorsec, akemi20, amedit, djsplatt, antonade, foobar7, paulos__, and nomadsyndiode for contributing reports, patches, testing, and review. Thank you for helping keep bbPress communities safe and reliable! <img alt=\"🙏\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f64f.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://downloads.wordpress.org/plugin/bbpress.2.6.17.zip\">Download bbPress 2.6.17</a> from WordPress.org, or update directly from your WordPress dashboard.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 16 Sep 2026 07:23:20 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"John James Jacoby\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:27;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:98:\"Open Channels FM: The Cost of Convenience How AI Agents and Security Initiatives Challenge Control\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2561898\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:105:\"https://openchannels.fm/the-cost-of-convenience-how-ai-agents-and-security-initiatives-challenge-control/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:98:\"AI agents handle daily tasks and IBM and Red Hat invest billions in open source software security.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 15 Sep 2026 16:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:28;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"Open Channels FM: Open Stacks, Federation, and the Changing Landscape of Software\";s:7:\"attribs\";a:0:{}